; ************************************************************************************************
;
;						Generator for data at YX, first token in A
;					  		CS succeed, A = type, CC = Fail.
;
; ************************************************************************************************

GeneratorProcess:
		stx 	zTemp0 						; save generation pointer in zTemp0
		sty 	zTemp0+1
		;
		sta 	zTemp1 						; first match token
		stz 	zTemp1+1
		;
		;		X16 shift of $CE
		;
		cmp 	#$CE 						; check if shift
		bne 	_GPNotShifted
		jsr 	GetNext 					; get the shifted token
		sta 	zTemp1+1 					; match CE xx
_GPNotShifted:
		;
		;		Find the generator entry.
		;		
_GPSearch:		
		lda 	(zTemp0) 					; reached end ?
		clc
		beq 	_GPExit
		;
		ldy 	#1 							; tokens match
		lda 	(zTemp0),y
		cmp 	zTemp1
		bne 	_GPNext

		lda 	zTemp1+1 					; 2nd token ?
		beq 	_GPFound

		iny 								; check match.
		cmp 	(zTemp0),y
		beq 	_GPFound
		;
_GPNext:	
		clc 								; follow to next
		lda 	zTemp0		
		adc 	(zTemp0)
		sta 	zTemp0
		bcc 	_GPSearch
		inc 	zTemp0+1
		bra 	_GPSearch
		;
_GPFound:	
		clc 								; skip to action bytes		
		lda 	zTemp0 						; <offset> <token lo> <token hi> first
		adc 	#3
		sta 	zTemp0
		bcc 	_GPNoCarry
		inc 	zTemp0+1
_GPNoCarry:
		;
		;		Main execution loop.
		;		
_GPLoop:
		jsr 	GeneratorExecute 			; execute one command
		bcc 	_GPLoop 					; go back if not completed.
		sec 								; return with CS.
_GPExit:
		rts

		.send  code		

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		genexec.asm
;		Purpose:	Generation executor
;		Created:	16th April 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code


; ************************************************************************************************
;
;						    Execute command pair at (zTemp0).
;					  	CS completed, A = type, CC = keep going.
;
; ************************************************************************************************

GeneratorExecute:
		jsr 	_GEFetchZTemp0 				; get next.
		pha 								; split into 2 nibbles
		lsr 	a
		lsr 	a
		lsr		a
		lsr 	a
		jsr 	_GEExecuteNibble 			; MSB first
		pla
		bcs 	_GEHaveCompleted
		jsr 	_GEExecuteNibble 			; LSB second
_GEHaveCompleted:		
		rts

; ------------------------------------------------------------------------------------------------
;										 Execute NIBL A
; ------------------------------------------------------------------------------------------------

_GEExecuteNibble:
		and 	#$0F
		asl 	a
		tax 	
		jmp 	(_GEExecuteVectors,x)

_GEExecuteVectors:
		.word 	_GEXNop 					; 0  (no operation)
		.word 	_GEXToken1 					; 1  (compile 1 byte token)
		.word 	_GEXToken2 					; 2  (compile 2 byte token)
		.word 	_GEXExecute 				; 3  (run arbitrary code)
		.word 	_GEXChannelExec 			; 4  (run arbitrary code with possible channel redirection)
		.word 	_GEXNop 					; 5
		.word 	_GEXExitNumber 				; 6  exit return ifloat32 type
		.word 	_GEXExitString 				; 7  exit return string type
		.word 	_GEXLParam 					; 8  check ( follows
		.word 	_GEXRParam 					; 9  check ) follows
		.word 	_GEXComma					; A  check , follows
		.word 	_GEXNop 					; B
		.word 	_GEXNop 					; C
		.word 	_GEXNop 					; D  
		.word 	_GEXNumber 					; E  compile get any number
		.word 	_GEXString 					; F  compile get any string

; ------------------------------------------------------------------------------------------------
;									 No Operations / Unused
; ------------------------------------------------------------------------------------------------

_GEXNop:				
		clc
		rts

; ------------------------------------------------------------------------------------------------
;									Compile 1/2 byte tokens
; ------------------------------------------------------------------------------------------------

_GEXToken2:
		jsr 	_GEFetchZTemp0
		jsr 	WriteCodeByte
_GEXToken1:
		jsr 	_GEFetchZTemp0
		jsr 	WriteCodeByte
		clc
		rts

; ------------------------------------------------------------------------------------------------
;										Exit with types
; ------------------------------------------------------------------------------------------------

_GEXExitNumber:
		lda 	#NSSIFloat
		sec
		rts

_GEXExitString:
		lda 	#NSSString
		sec
		rts

; ------------------------------------------------------------------------------------------------
;								 Check various characters follow
; ------------------------------------------------------------------------------------------------

_GEXLParam:
		lda 	#"("
		bra 	_GEXCheck
_GEXRParam:
		lda 	#")"
		bra 	_GEXCheck
_GEXComma:
		lda 	#","
_GEXCheck:
		sta 	zTemp2 						; save match
		jsr 	GetNextNonSpace 			; get next skipping spaces
		cmp 	zTemp2 						; check matches.
		bne 	_GEXSyntax
		clc
		rts
_GEXSyntax:
		.error_syntax

; ------------------------------------------------------------------------------------------------
;								 		Fetch, various types.
; ------------------------------------------------------------------------------------------------

_GEXNumber: 	
		jsr 	GEXCompileExpression 		; compile expression
		and 	#NSSTypeMask
		cmp  	#NSSIFloat
		bne 	_GEXType 	
		clc
		rts

_GEXString: 	
		jsr 	GEXCompileExpression 		; compile expression
		and 	#NSSTypeMask
		cmp  	#NSSString
		bne 	_GEXType 	
		clc
		rts

_GEXType:
		.error_type

; ------------------------------------------------------------------------------------------------
;							Execute 6502 code with Channel Redirect
; ------------------------------------------------------------------------------------------------

_GEXChannelExec:
		jsr 	ChannelPrefix 				; set up default
		jsr 	_GEXExecute
		php
		jsr 	ChannelPostfix 				; replace default.
		plp
		rts
		.debug

; ------------------------------------------------------------------------------------------------
;										Execute 6502 code
; ------------------------------------------------------------------------------------------------

_GEXExecute:
		jsr 	_GEFetchZTemp0 				; get vector		
		sta 	zTemp2 		
		jsr 	_GEFetchZTemp0
		sta 	zTemp2+1 		

		ldx 	zTemp0 						; push generation exec on to stack for reentrancy
		phx
		ldx 	zTemp0+1
		phx

		jsr 	_GECallZTemp2 				; execute code

		plx 								; recover generation exec
		stx 	zTemp0+1
		plx
		stx 	zTemp0
		rts		

_GECallZTemp2:
		jmp 	(zTemp2)		

; ------------------------------------------------------------------------------------------------
;										Get the next byte.
; ------------------------------------------------------------------------------------------------

_GEFetchZTemp0:
		lda 	(zTemp0)
		inc 	zTemp0
		bne 	_GEFZ0Skip
		inc 	zTemp0+1
_GEFZ0Skip:
		rts		

; ------------------------------------------------------------------------------------------------
;								Compile expression preserve state
; ------------------------------------------------------------------------------------------------

GEXCompileExpression:
		ldx 	zTemp0 						; push generation exec on to stack for reentrancy
		phx
		ldx 	zTemp0+1
		phx
		jsr 	CompileExpressionAt0 		; compile expression.
		plx 								; recover generation exec
		stx 	zTemp0+1
		plx
		stx 	zTemp0
		rts		

; ************************************************************************************************
;
;									Channel Prefix code.
;
; ************************************************************************************************

ChannelPrefix:
		lda 	#PCD_GETCHANNEL				; set channel onto stack
		jsr 	WriteCodeByte
		jsr 	GEXCompileExpression 		; channel #
		and 	#NSSTypeMask
		cmp 	#NSSIFloat
		bne 	_CPXType
		jsr 	CheckNextComma 				; check , follows.
		lda 	#PCD_SETCHANNEL				; set channel
		jsr 	WriteCodeByte
		clc
		rts
_CPXType:
		.error_type

; ************************************************************************************************
;
;									Channel Prefix code.
;
; ************************************************************************************************

ChannelPostfix:
		lda 	#PCD_SETCHANNEL				; set channel from TOS.
		jsr 	WriteCodeByte
		clc
		rts

		.send  code		

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		gensupport.asm
;		Purpose:	Support functions for generation
;		Created:	16th April 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;		MID$ has a support function because it has different numbers of parameters.
;		e.g. MID$(a$,b,c) or MID$(a$,b)
;
; ************************************************************************************************

OptionalParameterCompile:
		jsr 	LookNextNonSpace 			; what follows.
		;
		cmp 	#","
		bne 	_MidDefault
		jsr 	GetNext 					; consume ,
		jsr 	CompileExpressionAt0
		and 	#NSSTypeMask
		cmp 	#NSSIFloat
		bne 	MidFailType
		bra 	_MidComplete
_MidDefault:
		lda 	#255 						; default of 255
		jsr 	PushIntegerA
_MidComplete:
		clc
		rts

MidFailType:
		.error_type

; ************************************************************************************************
;
;		As OptionalParameterCompile, but defaulting to ZERO -- GP.CALL's registers, GP.INSTR's start.
;
;		No sentinel is involved and none is needed: an unspecified register genuinely IS zero, so
;		the runtime never has to test for "omitted" and carries no code to do it. Zero also fits
;		the one byte short constant path, so an omitted argument costs LESS here than a supplied
;		one -- the opposite of OptionalParameterCompile, whose 255 default cannot fit and emits a
;		two byte .byte instruction every time.
;
; ************************************************************************************************

OptionalZeroCompile:
		jsr 	LookNextNonSpace 			; what follows.
		cmp 	#","
		bne 	_ORCDefault
		jsr 	GetNext 					; consume ,
		jsr 	CompileExpressionAt0
		and 	#NSSTypeMask
		cmp 	#NSSIFloat
		bne 	MidFailType 				; which must be numeric
		clc
		rts
_ORCDefault:
		lda 	#0
		jsr 	PushIntegerA
		clc
		rts

; ************************************************************************************************
;
;		Push the constant 1, unconditionally, consuming nothing. It is a generator action rather
;		than an argument: a COMPOSITE keyword uses it to supply an argument the programmer did
;		not write, so that one keyword can run another's handler.
;
;		GP.CHAR x,y,char is the whole reason it exists -- it is GP.FILL x,y,1,1,char, and these
;		are the 1s. The alternative was a GP.CHAR handler in the GP runtime block, and that block
;		is all-or-nothing with 29 bytes left in it, so anything real would have crossed a page
;		and charged every program using ANY GP keyword 256 bytes -- twice, once in the object and
;		once off the bottom of its workspace.
;
;		It lives here, above ObjectBase, where compiler code is thrown away when the object is
;		written. These eight bytes cost a compiled program nothing at all.
;
; ************************************************************************************************

PushOneCompile:
		lda 	#1
		jsr 	PushIntegerA
		clc
		rts

; ************************************************************************************************
;
;		As OptionalParameterCompile, but for a trailing COLOUR argument (RECT/LINE/FRAME/OVAL/
;		RING). A palette index is 0..255, so 255 is a real colour and cannot double as the
;		"omitted" sentinel the way it can for sprite fields. The default is 256 instead -- out of
;		range for an 8-bit colour -- so the runtime (GraphicsColourOptional) reads a non-zero
;		high byte as "leave the current draw colour", and every explicit 0..255 still works.
;
; ************************************************************************************************

OptionalColourCompile:
		jsr 	LookNextNonSpace 			; what follows.
		cmp 	#","
		bne 	_OCCDefault
		jsr 	GetNext 					; consume ,
		jsr 	CompileExpressionAt0 		; the supplied colour
		and 	#NSSTypeMask
		cmp 	#NSSIFloat
		bne 	MidFailType 				; which must be numeric
		clc
		rts
_OCCDefault:
		lda 	#0 							; default of 256 = $0100: PushIntegerYA emits a 16-bit
		ldy 	#1 							; constant when Y (the high byte) is non-zero, and that
		jsr 	PushIntegerYA 				; high byte is what marks the colour as omitted.
		clc
		rts

; ************************************************************************************************
;
;		An optional *leading* numeric parameter, for commands that are valid with or without
;		an argument in stock BASIC (e.g. bare SLEEP as well as SLEEP <ticks>). Unlike
;		OptionalParameterCompile this argument has no leading comma to key off -- it is the
;		first and only parameter -- so absence is end-of-statement, tested exactly as
;		CommandRESTORE tests its optional line number (a ':' or EOL). When absent we push 0,
;		so bare SLEEP compiles to SLEEP 0 (an immediate return in the runtime handler).
;
; ************************************************************************************************

OptionalNumberCompile:
		jsr 	LookNextNonSpace 			; what follows the keyword ?
		cmp 	#':' 						; end of statement -> argument omitted
		beq 	_ONCDefault
		cmp 	#0 							; end of line     -> argument omitted
		beq 	_ONCDefault
		jsr 	CompileExpressionAt0 		; else compile the supplied expression
		and 	#NSSTypeMask
		cmp 	#NSSIFloat
		bne 	MidFailType 				; which must be numeric
		clc
		rts
_ONCDefault:
		lda 	#0 							; bare command == argument 0
		jsr 	PushIntegerA
		clc
		rts

; ************************************************************************************************
;
;		A generation helper for keywords that are recognised (so tokenised BASIC loads and
;		round-trips) but are not implemented by this version of the compiler. Rather than let
;		the term evaluator fall through to a bare "SYNTAX ERROR" -- which makes a valid-BASIC
;		keyword look like a typo -- we route the token here and raise NOT IMPLEMENTED, so the
;		user sees "NOT IMPLEMENTED @ <line>" and knows the feature, not their spelling, is the
;		problem. Used by POINTER and STRPTR (x16_unary.def): both expose the interpreter's
;		internal variable layout, which the compiled runtime stores differently, so honouring
;		them would silently misbehave rather than fail loudly. This never returns.
;
; ************************************************************************************************

UnsupportedCompile:
		.error_unimplemented

; ************************************************************************************************
;
;		NOT has a support function as its single expression parameter is done part way
;		up precedence
;
; ************************************************************************************************

NotUnaryCompile:
											; precedence of comparators
		lda 	PrecedenceTable+C64_EQUAL-C64_PLUS		
		jsr 	CompileExpressionAtA 		; evaluate at that level
		and 	#NSSTypeMask 				; check compile returns number.
		cmp 	#NSSIFloat
		bne 	MidFailType
		lda 	#PCD_NOT 					; and NOT it.
		jsr 	WriteCodeByte		
		rts

; ************************************************************************************************
;
;		StringVariableCompile WAS HERE, and went with GP.UPPER / GP.LOWER / GP.TRIM / GP.LTRIM /
;		GP.RTRIM on 1st September 2026 -- its only callers. They are GPC-BASIC/STRCASE.INC.BL now.
;
;		What it did is worth recording, because nothing replaces it. Those five modify the string
;		block the value points at, so handing them anything that is not a variable was a live
;		hazard rather than a nuisance: a LITERAL is pushed by CommandPushS pointing INTO THE
;		P-CODE, so GP.UPPER "abc" would rewrite the running program, and a temporary
;		(GP.UPPER A$+B$) would edit a block about to be reclaimed. Both would appear to work. So
;		it required a plain variable at COMPILE time, exactly as FOR requires one for its index,
;		and the hazard could not be expressed at all.
;
;		A GOSUB has no call site for the compiler to check, so STRCASE.INC.BL cannot have that
;		guarantee -- it takes a GP.STRPTR address and has no way to know where the address came
;		from. Its header says "do not pass a literal" in as many words. That is the one thing
;		moving those five out of the block genuinely gave up, and it should not be forgotten
;		merely because it is now a paragraph instead of a routine.
;
; ************************************************************************************************

; ************************************************************************************************
;
;		AN ARRAY, written with EMPTY parentheses -- GP.ARRPTR(A$()). Pushes the array's BASE
;		address and nothing else.
;
;		The parentheses are required and are not decoration: in BASIC A$ and A$() are different
;		variables, so accepting the bare name would find the SCALAR and silently hand back the
;		wrong thing. ExtractVariableName already sets NSSArray when it sees the "(" and consumes
;		it, so all that is left here is to insist on the ")".
;
;		Deliberately does NOT emit PCD_ARRAY1 -- that is the keyword that turns a base address
;		plus subscripts into an ELEMENT address, and the whole point here is to hand the runtime
;		the array itself. Pushing the base is the same idiom GetReferenceTerm uses just before it
;		emits that keyword: pretend the slot is an int16 and read it.
;
;		THE ELEMENT TYPE IS NOT CHECKED, and that is deliberate: GP.ARRPTR wants the address of a
;		float array just as much as a string one. There was a StringArrayCompile beside this, the
;		same routine with the type test added, and it went with GP.SORT on 1st September 2026 --
;		the type check moved into GPC-BASIC/SORT.INC.BL, which reads the array header itself.
;
; ************************************************************************************************

AnyArrayCompile:
		jsr 	GetNextNonSpace 			; a variable starts with a letter
		jsr 	CharIsAlpha
		bcc 	SACFail
		jsr 	ExtractVariableName 		; name in YX, type bits in X, "(" consumed if present
		cpx 	#0
		bpl 	SACFail 					; no "(" at all, so it is a scalar, not an array
		;
		phy 								; hold the name over the ")" check
		phx
		jsr 	GetNextNonSpace
		cmp 	#")"
		bne 	SACFailPull 				; empty parentheses only -- no subscript belongs here
		plx
		ply
		;
		jsr 	FindVariable 				; CS: exists, YX = its slot. CC: never mentioned.
		bcc 	SACFail
		lda 	#NSSIFloat+NSSIInt16 		; read the slot as an int16, which pushes the array's
		clc 								; base address without indexing into it
		jsr 	GetSetVariable
		clc
		rts

SACFailPull:
		plx
		ply
SACFail: 									; global, not _SACFail: 64tass scopes a _ label
		.error_syntax 						; to the enclosing global one, and BOTH entry
											; points above need to reach it

		.send code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		get.asm
;		Purpose:	Get from input
;		Created:	21st April 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;									Get input (also GET#)
;
; ************************************************************************************************

CommandGET:
		jsr 	LookNextNonSpace 			; # follows ?
		cmp 	#"#"
		bne 	CommandGetBody
		;
		jsr 	GetNext 					; consume #
		jsr 	ChannelPrefix 				; do it as GET#
		jsr 	CommandGetBody
		jsr 	ChannelPostfix
		rts

CommandGetBody:
		jsr 	GetNextNonSpace 			; get the first character
		jsr 	GetReferenceTerm 			; identify variable to assign to
		pha
		and 	#NSSTypeMask 				; check if it is a string
		cmp 	#NSSString
		bne 	_CGType

		lda 	#PCD_GET 					; compile GET
		jsr 	WriteCodeByte
		sec
		pla
		jsr		GetSetVariable
		rts

_CGType:
		.error_type

		.send code


; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		get.asm
;		Purpose:	Support functions.
;		Created:	15th April 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

; ************************************************************************************************
;
;											Code Reads
;
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;										Examine next character
;
; ************************************************************************************************

LookNext:
		lda 	(srcPtr) 
		rts

; ************************************************************************************************
;
;								Examine next non space character
;
; ************************************************************************************************		

LookNextNonSpace:
		lda 	(srcPtr)
		cmp		#' '
		beq 	_LNNSkip
		cmp 	#0
		rts
_LNNSkip:
		jsr 	GetNext
		bra 	LookNextNonSpace
				
; ************************************************************************************************
;
;										Get next character
;
; ************************************************************************************************

GetNext:
		lda 	(srcPtr) 					; get next
		inc 	srcPtr
		bne 	_GNSkip
		inc 	srcPtr+1
_GNSkip:		
		cmp 	#0
		rts
		
; ************************************************************************************************
;
;								  Get next non-space character
;
; ************************************************************************************************

GetNextNonSpace:
		jsr 	GetNext
		cmp 	#' '
		beq 	GetNextNonSpace
		cmp 	#0
		rts

; ************************************************************************************************
;
;						   Check if digit (CS = true, CC = false)
;
; ************************************************************************************************

CharIsDigit:
		cmp 	#"0"
		bcc 	CCFalse
		cmp 	#"9"+1
		bcs 	CCFalse
CCTrue:
		sec
		rts
CCFalse:
		clc
		rts

; ************************************************************************************************
;
;						   Check if alpha (CS = true, CC = false)
;
; ************************************************************************************************

CharIsAlpha:
		cmp 	#"A"
		bcc 	CCFalse
		cmp 	#"Z"+1
		bcs 	CCFalse
		bra 	CCTrue

; ************************************************************************************************
;
;				Convert to hex-style, e.g. 0-9 => 0-9, A-Z 10-35, CS true, CC false
;
; ************************************************************************************************

ConvertHexStyle:
		sec
		sbc 	#"0" 						; check in range 0-9 first
		bcc 	CCFalse
		cmp 	#9+1
		bcc 	CCTrue
		;
		sec 								; shift into hex space A=>0 Z=>25
		sbc 	#"A"-"0"
		bcc 	CCFalse
		cmp 	#26 						; past Z ?
		bcs 	CCFalse
		adc 	#10 						; make valid quasi-hex 0-35
		bra 	CCTrue

		.send 	code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************

; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		getname.asm
;		Purpose:	Get variable name
;		Created:	25th April 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

; ************************************************************************************************
;
;				  Extract a reference object name (variable, array, function)
;					  to XY. Error if failed. On entry A contains first
;
; ************************************************************************************************

		.section code

ExtractVariableName:
		jsr 	CharIsAlpha
		bcc 	_IVSyntax
		;
		;		One or two character variable ?
		;
		and 	#31 						; reduce first character to 5 bits
		sta 	zTemp1 						; we'll build it in zTemp1
		stz 	zTemp1+1
		;
		jsr 	LookNext 					; is there a second character ?
		jsr 	CharIsAlpha  				; must be alphanumeric 
		bcs 	_IVHasSecond
		jsr 	CharIsDigit
		bcc 	_IVCheckType
_IVHasSecond:
		and 	#63 						; 6 bit ASCII.
		sta 	zTemp1+1
_IVGetNextCheck:		
		jsr 	GetNext 					; consume it
		;
		;		Check for % $ postfix.
		;
_IVCheckType:
		jsr 	LookNext					; check if string follows.
		jsr 	CharIsAlpha
		bcs 	_IVGetNextCheck
		jsr 	CharIsDigit
		bcs 	_IVGetNextCheck

		ldx 	#NSSString
		cmp 	#"$"
		beq 	_IVHasType
		ldx 	#NSSIInt16 					; check if short int follows e.g. 16 bit
		cmp 	#"%"
		bne 	_IVCheckArray
_IVHasType:
		txa 								; Or X into zTemp1
		ora 	zTemp1
		sta 	zTemp1		
		jsr 	GetNext 					; consume it
		;
		;		Check for ( postfix
		;
_IVCheckArray:
		jsr 	LookNext 					; check if array follows
		cmp 	#"("
		bne 	_IVNotArray
		lda 	zTemp1 						; set array bit
		ora 	#NSSArray
		sta 	zTemp1		
		jsr 	GetNext 					; consume it
_IVNotArray:		
		ldx 	zTemp1
		ldy 	zTemp1+1
		rts

_IVSyntax:
		.error_syntax
		
		.send code

