; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		gpbank.asm
;		Purpose:	GP.BANKED / GP.ENDBANKED -- mark p-code that belongs in a RAM bank
;		Created:	5th September 2026
;		Reviewed: 	No
;		Author : 	Steven De George SR
;
; ************************************************************************************************
; ************************************************************************************************

		.section 	code

; ************************************************************************************************
;
;		GP.BANKED <bank>
;		...
;		GP.ENDBANKED
;
;		Marks a run of p-code as belonging at $A000 in the given RAM bank rather than in low
;		memory. Both are alone on their line; only GP.BANKED takes an operand, and it is a
;		DECIMAL CONSTANT, not an expression -- the number is patched into the program's
;		bootstrap at compile time, so there is nothing there to evaluate it.
;
;		THE TWO HANDLERS ONLY RECORD THE REGION. GPBankRelocate, further down this file, is what
;		acts on it: called from SaveCodeAndExit once the whole object is laid out, it lifts the
;		region out of the middle and puts it at the end, past the GP.ASM pool.
;
;		NAMED BANKED AND NOT BANK. BANK is the runtime statement that selects one, and this does
;		not select anything -- it is a compile time marker. Two keywords one letter apart, one of
;		which changes the hardware and one of which does not, is a trap not worth setting.
;
;		NO "T" ON EITHER, in commands.def. They write no keyword token, so ScanGPUsage cannot
;		see them and a program whose only GP.BASIC keyword is GP.BANKED stays GP OUT and pays
;		nothing for the GP runtime block -- the argument GP.ASM already makes for itself.
;
;		BOTH DISARM deferErrors FIRST. A block opener that fails with a SYNTAX error while the
;		deferral is armed is rolled back and replaced with a runtime throw-stub, so its opener
;		vanishes while the closer on a later line still compiles. The block is left with a
;		closer and no opener and the enclosing nesting is corrupted silently.
;
;		BOTH MUST RETURN CARRY CLEAR. A .def helper returning carry set makes the generator drop
;		every table element after it, with no error and no clue.
;
;		SEVERAL REGIONS A PROGRAM, each in its own bank, up to GPBANK_MAXREGIONS. What they may
;		NOT do is call each other: two regions live at the same $A000 in different banks, so a
;		branch from one to the other has no distance to travel and GPBankMakeOffset refuses it.
;		Everything reaches everything else the way it already does -- out to a low-memory shim
;		and back in.
;
;		EIGHT IS THE LIMIT and it comes from the bootstrap extension page, whose own table is
;		that long. A ninth GP.BANKED is refused rather than overrunning it.
;
; ************************************************************************************************

GPBANK_MAXREGIONS = 8 						; and eight is what the extension page's table holds

CommandGPBankedCompile:
		stz 	deferErrors 				; a block opener must never defer -- see the header
		lda 	gpBankState 				; 0 = never seen, 1 = open, 2 = closed
		cmp 	#1
		beq 	GPBankStructure 			; a GP.BANKED inside a region that is still open
		lda 	gpBankCount
		cmp 	#GPBANK_MAXREGIONS
		bcs 	GPBankStructure 			; ...or one region more than the table holds
		jsr 	GPBankCheckAlone 			; first on its line, and outside every block
		jsr 	GPBankReadNumber 			; the bank, into gpBankNumber
		jsr 	GPBankCheckBankFree 		; ...which no other region may already own
		lda 	#1
		sta 	gpBankState
		ldx 	gpBankCount
		lda 	gpBankNumber
		sta 	gpBankBanks,x
		txa 								; the two-byte tables want the subscript doubled
		asl 	a
		tax
		lda 	zTemp0 						; THE REGION STARTS AT ITS OWN LINE MARKER, so the line
		sta 	gpBankStarts,x 				; table entry for this line moves with it -- which is
		lda 	zTemp0+1 					; what lets the bridge below be an ordinary GOTO to an
		sta 	gpBankStarts+1,x 			; ordinary line number
		lda 	currentLineNumber 			; ...and this is the line number it goes to
		sta 	gpBankLinesIn,x
		lda 	currentLineNumber+1
		sta 	gpBankLinesIn+1,x
		clc
		rts

CommandGPEndBankedCompile:
		stz 	deferErrors
		lda 	gpBankState
		cmp 	#1 							; only a region that is open can be closed
		bne 	GPBankStructure
		jsr 	GPBankCheckAlone
		lda 	#2
		sta 	gpBankState
		lda 	gpBankCount
		asl 	a
		tax
		lda 	zTemp0 						; THE REGION ENDS AT THIS LINE'S MARKER, which stays
		sta 	gpBankEnds,x 				; behind in low memory: it is the first byte of what
		lda 	zTemp0+1 					; follows the region, not the last byte of it
		sta 	gpBankEnds+1,x
		lda 	currentLineNumber
		sta 	gpBankLinesOut,x
		lda 	currentLineNumber+1
		sta 	gpBankLinesOut+1,x
		inc 	gpBankCount 				; ONLY NOW is the region a region: an unclosed one is
		clc 								; a structure error and must not reach the relocator
		rts

;
;		A GLOBAL label, not a _ local one: 64tass scopes a _ label to the enclosing global, so a
;		local defined under the first routine cannot be branched to from the second.
;
GPBankStructure:
		.error_structure

; ************************************************************************************************
;
;		Read GP.BANKED's operand: a decimal constant, 1 to 255.
;
;		BANK 0 IS REFUSED. It is the KERNAL's -- its FAT32 buffers live there -- so a program
;		that put its code in it would work until the first file operation and then not.
;
;		No upper check beyond the byte. A 512K machine has banks 0..63 and a 2MB machine 0..255,
;		and which one this will run on is not a compile time fact.
;
; ************************************************************************************************

GPBankReadNumber:
		stz 	gpBankNumber
		jsr 	GetNextNonSpace 			; the first digit
		jsr 	CharIsDigit
		bcc 	GPBankBadNumber 			; no operand at all
_GBRNDigit:
		sec 								; gpBankNumber = gpBankNumber * 10 + digit
		sbc 	#"0"
		pha
		lda 	gpBankNumber
		asl 	a
		bcs 	GPBankBadNumber 			; over 255 at any point is not a bank
		sta 	gpBankNumber 				; n*2
		asl 	a
		bcs 	GPBankBadNumber
		asl 	a 							; n*8
		bcs 	GPBankBadNumber
		clc
		adc 	gpBankNumber 				; n*8 + n*2
		bcs 	GPBankBadNumber
		sta 	gpBankNumber
		pla
		clc
		adc 	gpBankNumber
		bcs 	GPBankBadNumber
		sta 	gpBankNumber
		jsr 	LookNext 					; another digit ?
		jsr 	CharIsDigit
		bcc 	_GBRNDone
		jsr 	GetNext
		bra 	_GBRNDigit
_GBRNDone:
		lda 	gpBankNumber
		beq 	GPBankBadNumber 			; bank 0 belongs to the KERNAL
		rts

GPBankBadNumber:
		.error_value

; ************************************************************************************************
;
;		Both markers have to be the FIRST statement on their line, and both have to be outside
;		every open block. Returns the address of this line's PCD_NEWCMD_LINE byte in zTemp0.
;
;		FIRST ON THE LINE, because that byte is the boundary. The compile loop writes one
;		PCD_NEWCMD_LINE per source line before dispatching any of its statements, so if the
;		marker is first then objPtr-1 is that byte -- and a region that begins and ends on a
;		line marker is a region whose two line table entries can move with it and be used as
;		branch targets. Written after another statement, objPtr-1 is the tail of that statement
;		and the boundary lands in the middle of it. Testing the byte is both the check and the
;		answer.
;
;		OUTSIDE EVERY BLOCK, because the region is spliced out with two plain GOTOs, and a GOTO
;		compiled inside a GP.DO or a GP.SELECT needs an .unwind in front of it to release the
;		frames it leaves. These two are written after compilation, where there is no such
;		machinery -- so require that there is nothing to unwind.
;
; ************************************************************************************************

GPBankCheckAlone:
		lda 	blockDepth 					; GP.DO nesting
		ora 	SelectDepth 				; ...and GP.SELECT
		bne 	GPBankStructure
		sec
		lda 	objPtr
		sbc 	#1
		sta 	zTemp0
		lda 	objPtr+1
		sbc 	#0
		sta 	zTemp0+1
		lda 	(zTemp0)
		cmp 	#PCD_NEWCMD_LINE
		bne 	GPBankStructure
		rts

; ************************************************************************************************
;
;		Lift the GP.BANKED region out of the middle of the object and put it at the end, past
;		the GP.ASM pool, on a page boundary.
;
;		Called from SaveCodeAndExit after AsmFlushPool and BEFORE FixBranches, so every branch is
;		still an unresolved line number and the only things that have to be corrected are the
;		line number table and the three places that hold a buffer ADDRESS.
;
;		BEFORE                                AFTER
;		+---------------------------------+   +---------------------------------+
;		| A   code before GP.BANKED       |   | A                               |
;		| B   the region     (gpBankStart)|   | GOTO the GP.BANKED line   3 bytes|
;		| C   code after     (gpBankEnd)  |   | C                               |
;		| $FF                             |   | $FF        <- low code ends here|
;		| the GP.ASM pool                 |   | the GP.ASM pool                 |
;		+---------------------------------+   | pad to a page boundary          |
;		                                      | B   the region                  |
;		                                      | GOTO the GP.ENDBANKED line      |
;		                                      | $FF                             |
;		                                      +---------------------------------+
;
;		THE TWO BRIDGES ARE ORDINARY GOTOs TO ORDINARY LINE NUMBERS, and that is the whole
;		trick. The region begins on the GP.BANKED line's marker byte and ends on the
;		GP.ENDBANKED line's, so both lines have a table entry pointing exactly at a boundary.
;		Correct the table and FixBranches -- which runs next, and knows nothing about any of
;		this -- resolves both bridges by the path it resolves every other GOTO. No new opcode,
;		no absolute operand, no back-patching.
;
;		THE POOL STAYS IN LOW MEMORY and the region goes ABOVE it. A blob is 65C02 code, and a
;		blob that changes the RAM bank -- STASH does -- must not itself be executing out of one.
;		Putting the pool below the region is also what lets the region's low memory copy be
;		reclaimed: the workspace can start where the region starts, because everything the
;		program still needs is underneath it.
;
;		THE REGION IS PAGE ALIGNED so the bootstrap's copy is a page loop rather than a byte
;		loop -- one byte of source page, one of page count, one of bank. There are 33 spare
;		bytes in the bootstrap and a byte loop does not fit in them.
;
;		THE FIRST $FF IS STILL THE LOW CODE'S END MARKER, so nothing downstream had to change
;		about where the pool goes. What did change is that two walkers now HOP over the pool to
;		reach the region -- see GPBankHop.
;
;		THE MOVE IS A ROTATION, done in place: shift the region and the whole tail up by three
;		to open the gap for the first bridge, reverse the region, reverse the tail, reverse the
;		pair -- which leaves the tail followed by the region -- then lift the region again by
;		the padding. No second buffer. The object buffer is the largest thing in low RAM
;		precisely because there is no room for one.
;
; ************************************************************************************************

GPBankRelocate:
		stz 	deferErrors
		lda 	gpBankState
		cmp 	#1
		beq 	_GBRUnclosed 				; a GP.BANKED that was never closed
		lda 	gpBankCount
		bne 	_GBRHaveRegion
		rts 								; no GP.BANKED in this program at all
_GBRUnclosed:
		jmp 	GPBankStructure
_GBRHaveRegion:
		;
		;		SHARED MODE ONLY. The correction below needs to know where the p-code will RUN,
		;		and in shared mode that is the constant PCODE_PAGE. Embedded, it depends on
		;		ScanGPUsage, which has not happened yet -- and there is no bootstrap there to do
		;		the copying either. Refusing is honest; guessing would miscompile silently.
		;
		lda 	gpBankShared
		bne 	_GBRPasses
		.error_unimplemented
;
;		ONE PASS A REGION, LAST REGION FIRST, AND EACH ONE LANDS BELOW THE LAST. gpBankCeiling
;		is the bottom of what earlier passes have already placed, and no pass touches a byte
;		above it: the rotation runs from the region up to the ceiling, and the placed block is
;		lifted bodily out of the way first. So the regions come to rest in SOURCE order, R0
;		lowest, each one starting on a page boundary and padded out to a whole number of pages
;		-- which is what lets the bootstrap copy the lot with one running source address.
;
;		A PASS MUST NOT DISTURB WHAT AN EARLIER PASS ALIGNED, and that is the whole reason for
;		the ceiling. Rotating each region to the top of the OBJECT instead would shift every
;		region already placed down by (3 - its length), which is not a whole number of pages, so
;		the second region to be moved would knock the first one off its page boundary and the
;		bootstrap would copy it from the wrong address. The block is lifted by a multiple of 256
;		here precisely so that cannot happen.
;
_GBRPasses:
		lda 	objPtr 						; nothing is placed yet, so the ceiling is the top
		sta 	gpBankCeiling
		lda 	objPtr+1
		sta 	gpBankCeiling+1
		lda 	gpBankCount
		sta 	gpBankPass
_GBRPass:
		dec 	gpBankPass
		jsr 	_GBRLoadRegion 				; the table -> the scalars this pass works in
		lda 	gpBankCeiling 				; Q, one past the tail -- NOT one past the object
		sta 	gpBankTailEnd
		lda 	gpBankCeiling+1
		sta 	gpBankTailEnd+1
		;
		;		The region's length, the tail's length, and where the region ends up.
		;
		sec
		lda 	gpBankEnd
		sbc 	gpBankStart
		sta 	gpBankLength 				; L
		lda 	gpBankEnd+1
		sbc 	gpBankStart+1
		sta 	gpBankLength+1

		sec
		lda 	gpBankTailEnd
		sbc 	gpBankEnd
		sta 	gpBankTailLen 				; TL
		lda 	gpBankTailEnd+1
		sbc 	gpBankEnd+1
		sta 	gpBankTailLen+1

		clc 								; R0 = start + 3 + TL, before padding
		lda 	gpBankStart
		adc 	#3
		sta 	gpBankMid
		lda 	gpBankStart+1
		adc 	#0
		sta 	gpBankMid+1
		clc
		lda 	gpBankMid
		adc 	gpBankTailLen
		sta 	gpBankMid
		lda 	gpBankMid+1
		adc 	gpBankTailLen+1
		sta 	gpBankMid+1

		sec 								; pad up to the next page. FreeMemory is page aligned
		lda 	#0 							; and so is the run base, so aligning in the buffer
		sbc 	gpBankMid 					; aligns it at run time.
		sta 	gpBankPad

		clc 								; R = R0 + pad
		lda 	gpBankMid
		adc 	gpBankPad
		sta 	gpBankNewBase
		lda 	gpBankMid+1
		adc 	#0
		sta 	gpBankNewBase+1
		;
		;		FILLER ABOVE THE END MARKER, so the region's SPAN is a whole number of pages and
		;		the region above it starts exactly where this one's pages stop. The span is the
		;		region, its exit bridge and the marker: L + 4. Nothing walks past the marker, so
		;		the filler is only ever copied into the bank and never read.
		;
		;		NONE OF IT FOR THE TOPMOST REGION, which is the one the FIRST pass places and the
		;		only one a program with a single region has. Nothing sits above it to be pushed
		;		off a page boundary, so writing up to 255 bytes to reach one would grow every
		;		banked object for no reason. Its last page is short and the bootstrap copies a
		;		few bytes of whatever follows into the bank behind it, which is what it has
		;		always done and what nothing ever reads.
		;
		stz 	gpBankFill
		lda 	gpBankPass
		inc 	a
		cmp 	gpBankCount
		bcs 	_GBRNoFill
		clc
		lda 	gpBankLength
		adc 	#4
		sta 	gpBankTemp
		sec
		lda 	#0
		sbc 	gpBankTemp
		sta 	gpBankFill
_GBRNoFill:
		;
		;		Room for the whole insertion: entry bridge, alignment padding, exit bridge, end
		;		marker and that filler. IT CAN PASS 256 -- padding and filler are a byte each and
		;		both can be 255 -- so the count is sixteen bits and not the X register.
		;
		;		Taken through WriteCodeByte rather than by moving objPtr, because that is the only
		;		place the object ceiling is tested. A program that no longer fits has to say
		;		PROGRAM TOO BIG here, not run off the top of the buffer.
		;
		lda 	objPtr
		sta 	gpBankOldTop
		lda 	objPtr+1
		sta 	gpBankOldTop+1
		clc
		lda 	gpBankPad
		adc 	#7
		sta 	gpBankRoom
		lda 	#0
		adc 	#0
		sta 	gpBankRoom+1
		clc
		lda 	gpBankRoom
		adc 	gpBankFill
		sta 	gpBankRoom
		lda 	gpBankRoom+1
		adc 	#0
		sta 	gpBankRoom+1
_GBRoom:
		lda 	gpBankRoom
		ora 	gpBankRoom+1
		beq 	_GBRoomDone
		lda 	#0
		jsr 	WriteCodeByte
		lda 	gpBankRoom
		bne 	_GBRoomNoBorrow
		dec 	gpBankRoom+1
_GBRoomNoBorrow:
		dec 	gpBankRoom
		bra 	_GBRoom
_GBRoomDone:
		;
		;		The three deltas every recorded address is corrected by. The tail moves from
		;		gpBankEnd down to start+3; the region moves to gpBankNewBase; and the block of
		;		regions an earlier pass placed moves UP, by the whole insertion.
		;
		sec
		lda 	#3
		sbc 	gpBankLength
		sta 	gpBankDelta+2
		lda 	#0
		sbc 	gpBankLength+1
		sta 	gpBankDelta+3

		sec
		lda 	gpBankNewBase
		sbc 	gpBankStart
		sta 	gpBankDelta
		lda 	gpBankNewBase+1
		sbc 	gpBankStart+1
		sta 	gpBankDelta+1

		sec 								; objPtr has already grown by the insertion
		lda 	objPtr
		sbc 	gpBankOldTop
		sta 	gpBankDelta+4
		lda 	objPtr+1
		sbc 	gpBankOldTop+1
		sta 	gpBankDelta+5
		;
		;		Lift the placed block out of the way, by exactly that. It is a whole number of
		;		pages -- the region's base is aligned and its span is whole pages, so what is
		;		inserted below the block has to be too -- which is what keeps every region an
		;		earlier pass aligned still aligned.
		;
		;		A no-op on the first pass, where the block is empty and the two ends meet.
		;
		lda 	gpBankCeiling
		sta 	gpBankMoveLow
		lda 	gpBankCeiling+1
		sta 	gpBankMoveLow+1
		lda 	gpBankOldTop
		sta 	zTemp0
		lda 	gpBankOldTop+1
		sta 	zTemp0+1
		lda 	objPtr
		sta 	zTemp1
		lda 	objPtr+1
		sta 	zTemp1+1
		jsr 	_GBShiftUp
		;
		;		Step one: shift the region and the tail up by three, to open the gap the entry
		;		bridge goes in.
		;
		lda 	gpBankStart
		sta 	gpBankMoveLow
		lda 	gpBankStart+1
		sta 	gpBankMoveLow+1
		lda 	gpBankTailEnd
		sta 	zTemp0
		lda 	gpBankTailEnd+1
		sta 	zTemp0+1
		clc
		lda 	gpBankTailEnd
		adc 	#3
		sta 	zTemp1
		lda 	gpBankTailEnd+1
		adc 	#0
		sta 	zTemp1+1
		jsr 	_GBShiftUp
		;
		;		Step two: rotate, so the tail comes first and the region follows it.
		;
		clc
		lda 	gpBankStart
		adc 	#3
		sta 	gpBankLow
		lda 	gpBankStart+1
		adc 	#0
		sta 	gpBankLow+1

		clc
		lda 	gpBankLow
		adc 	gpBankLength
		sta 	gpBankMid
		lda 	gpBankLow+1
		adc 	gpBankLength+1
		sta 	gpBankMid+1

		clc
		lda 	gpBankTailEnd
		adc 	#3
		sta 	gpBankHigh
		lda 	gpBankTailEnd+1
		adc 	#0
		sta 	gpBankHigh+1

		lda 	gpBankLow 					; reverse the region
		ldy 	gpBankLow+1
		ldx 	gpBankMid
		stx 	gpBankRevEnd
		ldx 	gpBankMid+1
		stx 	gpBankRevEnd+1
		jsr 	_GBReverse

		lda 	gpBankMid 					; reverse the tail
		ldy 	gpBankMid+1
		ldx 	gpBankHigh
		stx 	gpBankRevEnd
		ldx 	gpBankHigh+1
		stx 	gpBankRevEnd+1
		jsr 	_GBReverse

		lda 	gpBankLow 					; and the pair, leaving tail then region
		ldy 	gpBankLow+1
		ldx 	gpBankHigh
		stx 	gpBankRevEnd
		ldx 	gpBankHigh+1
		stx 	gpBankRevEnd+1
		jsr 	_GBReverse
		;
		;		Step three: lift the region again by the padding, so it starts on a page. The
		;		rotation left it at gpBankHigh - length; it has to end at newBase + length.
		;
		lda 	gpBankPad
		beq 	_GBRPadded 					; already aligned
		sec
		lda 	gpBankHigh
		sbc 	gpBankLength
		sta 	gpBankMoveLow 				; where the region sits now
		lda 	gpBankHigh+1
		sbc 	gpBankLength+1
		sta 	gpBankMoveLow+1
		lda 	gpBankHigh 					; ...and one past its last byte
		sta 	zTemp0
		lda 	gpBankHigh+1
		sta 	zTemp0+1
		clc
		lda 	gpBankHigh
		adc 	gpBankPad
		sta 	zTemp1
		lda 	gpBankHigh+1
		adc 	#0
		sta 	zTemp1+1
		jsr 	_GBShiftUp
_GBRPadded:
		;
		;		gpBankHigh is now one past the region: where the exit bridge goes.
		;
		clc
		lda 	gpBankNewBase
		adc 	gpBankLength
		sta 	gpBankHigh
		lda 	gpBankNewBase+1
		adc 	gpBankLength+1
		sta 	gpBankHigh+1
		;
		;		The two bridges, and the end marker of the whole object.
		;
		lda 	gpBankStart
		sta 	zTemp0
		lda 	gpBankStart+1
		sta 	zTemp0+1
		lda 	gpBankLineIn
		ldy 	gpBankLineIn+1
		jsr 	_GBWriteGoto

		lda 	gpBankHigh
		sta 	zTemp0
		lda 	gpBankHigh+1
		sta 	zTemp0+1
		lda 	gpBankLineOut
		ldy 	gpBankLineOut+1
		jsr 	_GBWriteGoto

		lda 	#$FF
		ldy 	#3
		sta 	(zTemp0),y
_GBRFixUp:
		;
		;		Everything that recorded a position in the buffer now has to be told.
		;
		jsr 	_GBFixLineTable
		jsr 	_GBFixRegions 				; BEFORE the .fngosub walk, which reads the new bases
		jsr 	_GBFixFnCalls
		jsr 	_GBFixAsmCalls
		jsr 	_GBFixPoolBase
		;
		;		WHERE THE WALK LEAVES OFF TO REACH THE REGION ABOVE THIS ONE. The walkers run to
		;		this region's own end marker and stop; one past it is where they must be sent on,
		;		and what they must be sent to is the next region's base -- which is exactly the
		;		page boundary the filler above reaches. The topmost region has nothing above it
		;		and so opens no hop.
		;
		;		RECORDED AFTER THE FIX-UPS, not before them. _GBFixRegions corrects every table
		;		entry an EARLIER pass wrote, and hops[pass+1] is one of them -- so writing this
		;		pass's own hop first would have it corrected a second time. The region it names
		;		is placed by a LATER pass, and its own base is written by that pass.
		;
		lda 	gpBankPass
		inc 	a
		cmp 	gpBankCount
		bcs 	_GBROnlyHop
		asl 	a
		tax
		clc
		lda 	gpBankHigh 					; the exit bridge is 3 and the marker 1
		adc 	#4
		sta 	gpBankHops,x
		lda 	gpBankHigh+1
		adc 	#0
		sta 	gpBankHops+1,x
_GBROnlyHop:
		;
		;		Leave the region's new bounds behind.
		;
		lda 	gpBankNewBase
		sta 	gpBankStart
		lda 	gpBankNewBase+1
		sta 	gpBankStart+1
		clc 								; one past the exit bridge
		lda 	gpBankHigh
		adc 	#3
		sta 	gpBankEnd
		lda 	gpBankHigh+1
		adc 	#0
		sta 	gpBankEnd+1
		;
		;		And how much the bootstrap has to move: the region, its exit bridge and the end
		;		marker, rounded up to whole pages. Any filler is inside that rounding rather than
		;		added to it -- it exists precisely to fill the part page this counts.
		;
		;		NOT objPtr MINUS THE BASE any more. That worked while the region was the last
		;		thing in the object, and with several it is only the topmost that still is.
		;
		clc
		lda 	gpBankLength
		adc 	#4
		sta 	gpBankTemp
		lda 	gpBankLength+1
		adc 	#0
		sta 	gpBankPages
		lda 	gpBankTemp 					; a part page needs one more
		beq 	_GBRWholePages
		inc 	gpBankPages
_GBRWholePages:
		;
		;		A REGION HAS TO FIT THE WINDOW. 32 pages is the whole of $A000-$BFFF, and nothing
		;		up to here has said no to a bigger one: the copy would simply run past $BFFF into
		;		the I/O page. It is checked HERE rather than at GP.ENDBANKED because this is where
		;		the padding and the two bridges are counted, and they are part of what has to fit.
		;
		lda 	gpBankPages
		cmp 	#33
		bcs 	_GBRTooBig
		jsr 	_GBRSaveRegion 				; ...and back into the table
		lda 	gpBankStart 				; the ceiling comes down onto it: the next pass may
		sta 	gpBankCeiling 				; not touch a byte from here up
		lda 	gpBankStart+1
		sta 	gpBankCeiling+1
		lda 	gpBankPass
		beq 	_GBRPlaced
		jmp 	_GBRPass
_GBRTooBig:
		.error_range
_GBRPlaced:
		;
		;		Nothing moves again, so the two things that had to wait for that can be settled:
		;		what a branch crossing into each region is out by, and where the whole run of
		;		them starts once the program is loaded.
		;
		;		THE CROSS-BOUNDARY CORRECTION. A branch offset is target minus source computed in
		;		BUFFER addresses, which works because every byte has the same buffer-to-run delta
		;		and the two cancel in the subtraction. A region's delta is different -- buffer to
		;		$A000, not buffer to the p-code base -- so a branch with one end each side comes
		;		out wrong by exactly the difference, and only such a branch does.
		;
		;		It is a whole number of PAGES: both bases are page aligned and so is every region.
		;		So the correction is one byte, added to or taken off the offset's high half.
		;
		ldx 	#0
_GBRCross:
		txa
		asl 	a
		tay
		clc
		lda 	gpBankStarts+1,y 			; the page this region WOULD have run at in low memory
		adc 	gpBankRunPage
		inc 	a 							; ...plus one, for the BOOTSTRAP EXTENSION PAGE. Only a
											; banked program carries it, and this routine only runs
											; for a banked program, so the +1 is unconditional:
											; low p-code starts at $0A00 here, not $0900.
		sta 	gpBankTemp
		sec
		lda 	#$A0 						; ...against the page it is actually going to -- and
		sbc 	gpBankTemp 					; every region goes to $A000, in its own bank
		sta 	gpBankCrossings,x
		inx
		cpx 	gpBankCount
		bcc 	_GBRCross
		;
		;		...and where the whole run of them sits once the program is loaded. That is the
		;		LOWEST region, which is region 0: the passes go downwards and each one lands
		;		below the last, so the regions end up in source order with R0 at the bottom. One
		;		address is enough because they are contiguous in whole pages.
		;
		clc
		lda 	gpBankStarts+1
		adc 	gpBankRunPage
		inc 	a
		sta 	gpBankRunBase
		jsr 	_GBRFindLowEnd
		lda 	#1
		sta 	gpBankActive
		rts

; ************************************************************************************************
;
;		Where the walk leaves LOW MEMORY, which is hops[0]: the first region is reached from
;		there and every other one from the region below it.
;
;		FOUND BY WALKING, not by arithmetic. It used to be "one past the tail", and with a single
;		region that was the same thing -- the tail ended at the low code's own end marker. With
;		several it is not: each pass leaves its alignment padding behind in what the NEXT pass
;		treats as tail, so one past the tail is one past a stretch of padding the walkers stop
;		short of. They stop at the marker, so this stops where they do.
;
;		gpBankActive is still 0 here, so the walk cannot hop -- which is the point. objPtr is the
;		end of the object and WriteObjectCode streams up to it, so it is put back.
;
;		THE PADDING BELOW THE FIRST REGION IS DEAD SPACE, up to 255 bytes for every region after
;		the first. It sits below the region and so counts as low p-code. Worth reclaiming if a
;		program ever gets close enough to the ceiling to care.
;
; ************************************************************************************************

_GBRFindLowEnd:
		lda 	objPtr
		sta 	gpBankSave
		lda 	objPtr+1
		sta 	gpBankSave+1
		lda 	#BLC_RESETOUT 				; the compiler library cannot name FreeMemory -- the
		jsr 	CallAPIHandler 				; same reason FixBranches rewinds this way
_GBRFLELoop:
		jsr 	MoveObjectForward
		bcc 	_GBRFLELoop
		lda 	objPtr
		sta 	gpBankHops
		lda 	objPtr+1
		sta 	gpBankHops+1
		lda 	gpBankSave
		sta 	objPtr
		lda 	gpBankSave+1
		sta 	objPtr+1
		rts

;
;		The pass's region, out of the table and back into it. X indexes the byte tables and the
;		two-byte ones want it doubled, so the subscript is built once rather than at every field.
;
;		LOAD IS BEFORE THE ROTATION and SAVE IS AFTER, and in between gpBankStart and gpBankEnd
;		mean what they meant when they went in -- where the region was. GPBankAdjust reads them
;		that whole time to decide which side of the move an address was on, which is why the
;		post-move values go back through here at the end and not the moment they are known.
;
_GBRLoadRegion:
		ldx 	gpBankPass
		lda 	gpBankBanks,x
		sta 	gpBankNumber
		txa
		asl 	a
		tax
		lda 	gpBankStarts,x
		sta 	gpBankStart
		lda 	gpBankStarts+1,x
		sta 	gpBankStart+1
		lda 	gpBankEnds,x
		sta 	gpBankEnd
		lda 	gpBankEnds+1,x
		sta 	gpBankEnd+1
		lda 	gpBankLinesIn,x
		sta 	gpBankLineIn
		lda 	gpBankLinesIn+1,x
		sta 	gpBankLineIn+1
		lda 	gpBankLinesOut,x
		sta 	gpBankLineOut
		lda 	gpBankLinesOut+1,x
		sta 	gpBankLineOut+1
		rts

_GBRSaveRegion:
		ldx 	gpBankPass
		lda 	gpBankPages
		sta 	gpBankPageCounts,x
		txa
		asl 	a
		tax
		lda 	gpBankStart
		sta 	gpBankStarts,x
		lda 	gpBankStart+1
		sta 	gpBankStarts+1,x
		lda 	gpBankEnd
		sta 	gpBankEnds,x
		lda 	gpBankEnd+1
		sta 	gpBankEnds+1,x
		rts

; ************************************************************************************************
;
;		The regions an EARLIER pass already placed. Each of them sits above the region this pass
;		took, so this pass's rotation moved every one of them, and their recorded base, end and
;		hop are ordinary buffer addresses that move like any other -- GPBankAdjust knows what by.
;
;		A program with one region never enters the loop.
;
; ************************************************************************************************

_GBFixRegions:
		lda 	gpBankPass
		sta 	gpBankTemp
_GBFRNext:
		inc 	gpBankTemp
		lda 	gpBankTemp
		cmp 	gpBankCount
		bcs 	_GBFRDone
		asl 	a
		sta 	gpBankTemp2 				; the doubled subscript, for all three tables
		.set16 	zTemp0, gpBankStarts
		jsr 	_GBFRField
		.set16 	zTemp0, gpBankEnds
		jsr 	_GBFRField
		.set16 	zTemp0, gpBankHops
		jsr 	_GBFRField
		bra 	_GBFRNext
_GBFRDone:
		rts

;
;		One two-byte table entry, through GPBankAdjust: the table's base in zTemp0 and the
;		doubled subscript in gpBankTemp2. Written once and called three times rather than
;		spelled out three times, which is 50 bytes of a compiler that is measured against the
;		object buffer it shares a page boundary with -- see [[compiler-must-not-cap-program-size]].
;
;		GPBankAdjust reads and writes zTemp1 and corrupts X, and touches nothing else.
;
_GBFRField:
		ldy 	gpBankTemp2
		lda 	(zTemp0),y
		sta 	zTemp1
		iny
		lda 	(zTemp0),y
		sta 	zTemp1+1
		jsr 	GPBankAdjust
		ldy 	gpBankTemp2
		lda 	zTemp1
		sta 	(zTemp0),y
		iny
		lda 	zTemp1+1
		sta 	(zTemp0),y
		rts

_GBFixPoolBase:
		lda 	AsmPoolLen
		ora 	AsmPoolLen+1
		beq 	_GBFPBOut
		lda 	AsmPoolBase
		sta 	zTemp1
		lda 	AsmPoolBase+1
		sta 	zTemp1+1
		jsr 	GPBankAdjust
		lda 	zTemp1
		sta 	AsmPoolBase
		lda 	zTemp1+1
		sta 	AsmPoolBase+1
_GBFPBOut:
		rts

; ************************************************************************************************
;
;		Write .goto <line YA> at zTemp0.
;
; ************************************************************************************************

_GBWriteGoto:
		pha 								; line low
		phy 								; line high
		lda 	#PCD_CMD_GOTO
		sta 	(zTemp0)
		pla 								; high comes back off first
		tax
		pla 								; low
		ldy 	#1
		sta 	(zTemp0),y
		txa
		iny
		sta 	(zTemp0),y
		rts

; ************************************************************************************************
;
;		Move the bytes in [gpBankMoveLow, zTemp0) up so that they end at zTemp1. Copied from the
;		top down, so the source and the destination may overlap.
;
; ************************************************************************************************

_GBShiftUp:
		lda 	zTemp0
		cmp 	gpBankMoveLow
		bne 	_GBSUByte
		lda 	zTemp0+1
		cmp 	gpBankMoveLow+1
		beq 	_GBSUDone
_GBSUByte:
		lda 	zTemp0
		bne 	_GBSUNoBorrow0
		dec 	zTemp0+1
_GBSUNoBorrow0:
		dec 	zTemp0
		lda 	zTemp1
		bne 	_GBSUNoBorrow1
		dec 	zTemp1+1
_GBSUNoBorrow1:
		dec 	zTemp1
		lda 	(zTemp0)
		sta 	(zTemp1)
		bra 	_GBShiftUp
_GBSUDone:
		rts

; ************************************************************************************************
;
;		Reverse the bytes from YA up to gpBankRevEnd, which is one past the last. An empty range
;		and a range of one byte both fall straight out.
;
; ************************************************************************************************

_GBReverse:
		sta 	zTemp0 						; zTemp0 = the first byte
		sty 	zTemp0+1
		lda 	gpBankRevEnd 				; zTemp1 = the LAST byte, one below the end
		sta 	zTemp1
		lda 	gpBankRevEnd+1
		sta 	zTemp1+1
		lda 	zTemp1
		bne 	_GBRevNoBorrow
		dec 	zTemp1+1
_GBRevNoBorrow:
		dec 	zTemp1
_GBRevLoop:
		lda 	zTemp0+1 					; done once the two pointers meet or cross
		cmp 	zTemp1+1
		bcc 	_GBRevSwap
		bne 	_GBRevDone
		lda 	zTemp0
		cmp 	zTemp1
		bcs 	_GBRevDone
_GBRevSwap:
		lda 	(zTemp0)
		tax
		lda 	(zTemp1)
		sta 	(zTemp0)
		txa
		sta 	(zTemp1)
		inc 	zTemp0
		bne 	_GBRevNoCarry
		inc 	zTemp0+1
_GBRevNoCarry:
		lda 	zTemp1
		bne 	_GBRevNoBorrow2
		dec 	zTemp1+1
_GBRevNoBorrow2:
		dec 	zTemp1
		bra 	_GBRevLoop
_GBRevDone:
		rts

; ************************************************************************************************
;
;		Every entry in the line number table holds the compile time address of the line it
;		names, and the whole point of moving the region on line boundaries is that these stay
;		usable: FixBranches resolves both bridges through them a moment from now, and the map
;		file is written from them afterwards.
;
;		The table is walked exactly as WriteMapFile walks it -- 4 byte entries growing DOWN from
;		compilerEndHigh:$00 to lineNumberTable -- and the window is opened and closed once per
;		entry rather than held across the loop, for the reason x16_storage.inc gives.
;
; ************************************************************************************************

_GBFixLineTable:
		lda 	compilerEndHigh
		sta 	gpBankWalk+1
		stz 	gpBankWalk
_GBFLTLoop:
		sec 								; down one entry
		lda 	gpBankWalk
		sbc 	#4
		sta 	gpBankWalk
		lda 	gpBankWalk+1
		sbc 	#0
		sta 	gpBankWalk+1
		lda 	gpBankWalk+1 				; stop below the last (lowest) entry
		cmp 	lineNumberTable+1
		bcc 	_GBFLTDone
		bne 	_GBFLTEntry
		lda 	gpBankWalk
		cmp 	lineNumberTable
		bcc 	_GBFLTDone
_GBFLTEntry:
		lda 	gpBankWalk
		sta 	zTemp0
		lda 	gpBankWalk+1
		sta 	zTemp0+1
		.storage_access
		ldy 	#2 							; the address is at +2,+3
		lda 	(zTemp0),y
		sta 	zTemp1
		iny
		lda 	(zTemp0),y
		sta 	zTemp1+1
		.storage_release
		jsr 	GPBankAdjust
		.storage_access
		ldy 	#2
		lda 	zTemp1
		sta 	(zTemp0),y
		iny
		lda 	zTemp1+1
		sta 	(zTemp0),y
		.storage_release
		bra 	_GBFLTLoop
_GBFLTDone:
		rts

; ************************************************************************************************
;
;		.fngosub is the one p-code operand that is an absolute buffer address at this point --
;		FixBranches turns it into an offset a moment later, but it is not one yet, so a body or
;		a call that moved has to be corrected first.
;
;		The walk is MoveObjectForward's, which steps by real instruction size, so an operand
;		byte that happens to equal PCD_CMD_FNGOSUB is never read as one. It runs BEFORE the hop
;		is opened, so it stops at the low code's $FF -- and then does the region as a second
;		range, because a DEF FN inside one is perfectly legal.
;
;		objPtr is put back afterwards: it is the end of the object, and WriteObjectCode streams
;		up to it.
;
; ************************************************************************************************

_GBFixFnCalls:
		lda 	objPtr
		sta 	gpBankSave
		lda 	objPtr+1
		sta 	gpBankSave+1
		lda 	#BLC_RESETOUT 				; the compiler library cannot name FreeMemory -- the
		jsr 	CallAPIHandler 				; same reason FixBranches rewinds this way
		jsr 	_GBFFCRange 				; the low code
		lda 	gpBankNewBase 				; ...then the region this pass just moved
		sta 	objPtr
		lda 	gpBankNewBase+1
		sta 	objPtr+1
		jsr 	_GBFFCRange
		;
		;		...and then every region an earlier pass placed. They moved too, _GBFixRegions
		;		has just said where to, and a DEF FN inside one is as legal as anywhere else.
		;
		lda 	gpBankPass
		sta 	gpBankTemp
_GBFFCRegion:
		inc 	gpBankTemp
		lda 	gpBankTemp
		cmp 	gpBankCount
		bcs 	_GBFFCEnd
		asl 	a
		tax
		lda 	gpBankStarts,x
		sta 	objPtr
		lda 	gpBankStarts+1,x
		sta 	objPtr+1
		jsr 	_GBFFCRange
		bra 	_GBFFCRegion
_GBFFCEnd:
		lda 	gpBankSave
		sta 	objPtr
		lda 	gpBankSave+1
		sta 	objPtr+1
		rts

_GBFFCRange:
		lda 	(objPtr)
		cmp 	#PCD_CMD_FNGOSUB
		bne 	_GBFFCNext
		ldy 	#1
		lda 	(objPtr),y
		sta 	zTemp1
		iny
		lda 	(objPtr),y
		sta 	zTemp1+1
		jsr 	GPBankAdjust
		ldy 	#1
		lda 	zTemp1
		sta 	(objPtr),y
		iny
		lda 	zTemp1+1
		sta 	(objPtr),y
_GBFFCNext:
		jsr 	MoveObjectForward
		bcc 	_GBFFCRange
		rts

; ************************************************************************************************
;
;		GP.ASM's blob calls are the other absolute address, and they are not in the object at
;		all -- a blob call's fixup records WHERE IN THE BUFFER its .word operand sits, so that
;		AsmPatchAll can fill it in once the run base is known. That target is a buffer address
;		like any other and moves with the byte it names. The other two fixup kinds hold pool and
;		workspace offsets, which this does not touch.
;
; ************************************************************************************************

_GBFixAsmCalls:
		lda 	AsmFixupCount
		beq 	_GBFACDone
		stz 	gpBankIdx
_GBFACLoop:
		lda 	gpBankIdx
		asl 	a
		tax 								; the two byte arrays index by count*2
		ldy 	gpBankIdx 					; ...and the kind array by count
		.asm_access
		lda 	AsmFixKind,y
		sta 	gpBankKind
		lda 	AsmFixTarget,x
		sta 	zTemp1
		lda 	AsmFixTarget+1,x
		sta 	zTemp1+1
		.asm_release
		lda 	gpBankKind
		cmp 	#AFIX_CALL 					; only a blob call's target is a buffer address
		bne 	_GBFACNext
		jsr 	GPBankAdjust 				; corrupts X, so rebuild the subscript after it
		lda 	gpBankIdx
		asl 	a
		tax
		.asm_access
		lda 	zTemp1
		sta 	AsmFixTarget,x
		lda 	zTemp1+1
		sta 	AsmFixTarget+1,x
		.asm_release
_GBFACNext:
		inc 	gpBankIdx
		lda 	gpBankIdx
		cmp 	AsmFixupCount
		bcc 	_GBFACLoop
_GBFACDone:
		rts

; ************************************************************************************************
;
;		EVERY GLOBAL BELOW THIS LINE, AND NOWHERE ELSE.
;
;		64tass scopes a "_" label to the enclosing GLOBAL, so a global dropped in among another
;		routine's locals starts a new scope and every branch to a local defined after it stops
;		resolving -- "not defined symbol '_GBShiftUp'", and so on down the file. GPBankRelocate's
;		helpers run from _GBWriteGoto to _GBFixAsmCalls; put a new global in the middle of them
;		and the build breaks in six places that have nothing to do with what was added. Twice, so
;		far.
;
; ************************************************************************************************

; ************************************************************************************************
;
;		TWO REGIONS IN ONE BANK would put the second at $A000 on top of the first, and the only
;		symptom would be the first one's code running as whatever the second one's is. The bank
;		is a constant read at compile time, so this costs one walk of a table that is at most
;		eight long, once per GP.BANKED.
;
;		BAD VALUE, reported at the GP.BANKED whose operand is the repeat -- which is the second
;		of the two, and the one the user can move.
;
; ************************************************************************************************

GPBankCheckBankFree:
		ldx 	#0
_GBCBFNext:
		cpx 	gpBankCount
		bcs 	_GBCBFOkay
		lda 	gpBankBanks,x
		cmp 	gpBankNumber
		beq 	_GBCBFTaken
		inx
		bra 	_GBCBFNext
_GBCBFOkay:
		rts
_GBCBFTaken:
		.error_value

; ************************************************************************************************
;
;		zTemp1 holds an address recorded before the move. Replace it with where that byte is
;		now. Four cases and three deltas: below the region nothing moved, inside it everything
;		moved to the new base, after it everything moved down by the region minus the bridge,
;		and above the ceiling -- the regions an earlier pass already placed -- everything moved
;		UP by the whole insertion.
;
;		Corrupts X.
;
; ************************************************************************************************

GPBankAdjust:
		lda 	zTemp1+1 					; below the region ? then it did not move
		cmp 	gpBankStart+1
		bcc 	_GBADone
		bne 	_GBANotBelow
		lda 	zTemp1
		cmp 	gpBankStart
		bcc 	_GBADone
_GBANotBelow:
		ldx 	#0 							; inside the region
		lda 	zTemp1+1
		cmp 	gpBankEnd+1
		bcc 	_GBAAdd
		bne 	_GBAAfter
		lda 	zTemp1
		cmp 	gpBankEnd
		bcc 	_GBAAdd
_GBAAfter:
		ldx 	#2 							; ...or after it, in the tail
		lda 	zTemp1+1
		cmp 	gpBankCeiling+1
		bcc 	_GBAAdd
		bne 	_GBAPlaced
		lda 	zTemp1
		cmp 	gpBankCeiling
		bcc 	_GBAAdd
_GBAPlaced:
		ldx 	#4 							; ...or up in a region an earlier pass placed, which
											; this pass lifted bodily rather than rotating
_GBAAdd:
		clc
		lda 	zTemp1
		adc 	gpBankDelta,x
		sta 	zTemp1
		lda 	zTemp1+1
		adc 	gpBankDelta+1,x
		sta 	zTemp1+1
_GBADone:
		rts

; ************************************************************************************************
;
;		The walk over the object runs out of low memory at the $FF that ends it, and the region
;		is on the far side of the GP.ASM pool. Called by everything that walks the whole object
;		-- FixBranches' main loop and its unwind-depth walk, and ScanGPUsage -- when
;		MoveObjectForward has just said "end".
;
;		Carry CLEAR means it hopped and there is more to walk; carry SET means that really was
;		the end. A program with no GP.BANKED always gets carry set, so nothing changes for it.
;
; ************************************************************************************************

GPBankHop:
		lda 	gpBankActive
		beq 	_GBHEnd
		ldx 	#0
_GBHNext:
		cpx 	gpBankCount
		bcs 	_GBHEnd
		txa
		asl 	a
		tay
		lda 	objPtr
		cmp 	gpBankHops,y
		bne 	_GBHSkip
		lda 	objPtr+1
		cmp 	gpBankHops+1,y
		bne 	_GBHSkip
		lda 	gpBankStarts,y 				; the hop lands on the region itself
		sta 	objPtr
		lda 	gpBankStarts+1,y
		sta 	objPtr+1
		clc
		rts
_GBHSkip:
		inx
		bra 	_GBHNext
_GBHEnd:
		sec
		rts


; ************************************************************************************************
;
;		STRMakeOffset, plus the correction a branch needs when exactly one of its ends is in the
;		banked region. YA is the target on the way in and the finished offset on the way out, so
;		it drops straight into FixBranches' two patch tails in place of STRMakeOffset.
;
;		Both ends the same side and nothing changes -- which is every branch in a program with no
;		GP.BANKED in it, and almost every branch in one that has.
;
; ************************************************************************************************

GPBankMakeOffset:
		sta 	gpBankTarget
		sty 	gpBankTarget+1
		jsr 	STRMakeOffset 				; YA = the offset, objPtr = the branch it sits at
		sta 	gpBankOffset
		sty 	gpBankOffset+1
		lda 	gpBankActive
		beq 	_GBMOOut
		lda 	objPtr 						; which side is the branch on ?
		ldy 	objPtr+1
		jsr 	_GBMOSide
		sta 	gpBankSideFrom
		lda 	gpBankTarget 				; ...and the target ?
		ldy 	gpBankTarget+1
		jsr 	_GBMOSide
		sta 	gpBankSideTo
		cmp 	gpBankSideFrom
		beq 	_GBMOOut 					; the same side: the deltas cancel as they always did
		;
		;		ONE END IN A REGION AND THE OTHER IN LOW MEMORY is what the correction is for.
		;		ONE END IN EACH OF TWO REGIONS cannot be corrected at all: both regions run at
		;		$A000, in different banks, so the branch has no distance to travel and no offset
		;		describes it. Refused here rather than miscompiled -- and it is the same rule the
		;		library already works to, where everything reaches everything else by going out
		;		to a low-memory shim and back in.
		;
		lda 	gpBankSideFrom
		beq 	_GBMOInto 					; 0 = low memory, so this one goes INTO a region
		ldx 	gpBankSideTo
		bne 	_GBMOCross 					; both ends in regions, and not the same one
		ldx 	gpBankSideFrom 				; out of a region, into low memory
		dex
		sec
		lda 	gpBankOffset+1
		sbc 	gpBankCrossings,x
		sta 	gpBankOffset+1
		bra 	_GBMOOut
_GBMOInto:
		ldx 	gpBankSideTo 				; out of low memory, into a region
		dex
		clc
		lda 	gpBankOffset+1
		adc 	gpBankCrossings,x
		sta 	gpBankOffset+1
_GBMOOut:
		lda 	gpBankOffset
		ldy 	gpBankOffset+1
		rts

_GBMOCross:
		.error_unimplemented

;
;		YA is an address in the object buffer. A comes back 0 if it is in low memory, or the
;		region's number PLUS ONE if it is inside one -- so that "same side" is still a single
;		compare, and which region it was is still in hand for the correction.
;
;		The regions are the last things in the buffer, in source order with a few bytes of page
;		filler between them. Nothing branches at filler, so an address in none of them is in
;		low memory.
;
_GBMOSide:
		sta 	gpBankTemp
		sty 	gpBankTemp2
		ldx 	#0
_GBMOSNext:
		cpx 	gpBankCount
		bcs 	_GBMOLow
		txa
		asl 	a
		tay
		lda 	gpBankTemp2 				; below this region ? then it is not this one
		cmp 	gpBankStarts+1,y
		bcc 	_GBMOSSkip
		bne 	_GBMOSNotBelow
		lda 	gpBankTemp
		cmp 	gpBankStarts,y
		bcc 	_GBMOSSkip
_GBMOSNotBelow:
		lda 	gpBankTemp2 				; ...and before its end ?
		cmp 	gpBankEnds+1,y
		bcc 	_GBMOHigh
		bne 	_GBMOSSkip
		lda 	gpBankTemp
		cmp 	gpBankEnds,y
		bcc 	_GBMOHigh
_GBMOSSkip:
		inx
		bra 	_GBMOSNext
_GBMOHigh:
		txa
		inc 	a
		rts
_GBMOLow:
		lda 	#0
		rts


; ************************************************************************************************
;
;		BANK <n> INSIDE A GP.BANKED REGION IS REFUSED, and this is the whole of that check.
;
;		Banked p-code is FETCHED from $A000, so the bank it lives in has to be selected at every
;		fetch. BANK writes the hardware register and leaves it there (x16_peekpoke.asm), so a
;		BANK compiled into the region kills the very next instruction -- not at the BANK, at
;		whatever followed it, which is the worst possible place to be told.
;
;		PEEK and POKE are NOT affected and need no check: they save the selected bank, switch,
;		access, and put it straight back, so they work from banked code unchanged. BANK is the
;		one statement that leaves the register somewhere else.
;
;		NOT IMPLEMENTED rather than a new error text. Every error string is shared with the
;		RUNTIME image, so a message for this would be about twenty bytes off every compiled
;		program's workspace to name a compile-time mistake. The line number points at the BANK.
;
;		The consequence for the library is worth stating: A MODULE THAT DRIVES BANKS STAYS IN
;		LOW MEMORY. STASH is the one that does, and it is 376 bytes.
;
; ************************************************************************************************

CommandBankGuard:
		lda 	gpBankState 				; 1 = a region is open, so this BANK is inside it
		cmp 	#1
		beq 	_CBGInside
		clc 								; a .def helper returning carry set makes the generator
		rts 								; drop every table element after it, silently
_CBGInside:
		.error_unimplemented


		.send 	code

		.section storage
gpBankState:									; 0 none, 1 open, 2 closed. Reset in compiler.asm
		.fill 	1
gpBankActive:									; 1 once the region has been relocated -- opens the hop
		.fill 	1
gpBankNumber:									; the bank GP.BANKED named
		.fill 	1
gpBankStart:									; where the region starts in the object buffer -- and
		.fill 	2 								; where it ended up, once GPBankRelocate has run
gpBankEnd:										; and one past where it ends
		.fill 	2
gpBankLineIn:									; the GP.BANKED line, which the entry bridge targets
		.fill 	2
gpBankLineOut:									; the GP.ENDBANKED line, for the exit bridge
		.fill 	2
gpBankLength:									; the region's size in bytes
		.fill 	2
gpBankTailLen:									; and the size of everything that followed it
		.fill 	2
gpBankTailEnd:									; one past the whole object, before the move
		.fill 	2
gpBankNewBase:									; where the region is moved to, page aligned
		.fill 	2
gpBankPad:										; bytes of padding that alignment needed
		.fill 	1
gpBankDelta:									; three 16 bit deltas, and GPBankAdjust indexes them:
		.fill 	6 								; inside the region, after it, and the placed block
gpBankCeiling:									; where the regions an earlier pass placed begin --
		.fill 	2 								; the top of what this pass is allowed to move
gpBankFill:										; bytes of filler above the region's end marker, to
		.fill 	1 								; make its span a whole number of pages
gpBankRoom:										; the whole insertion, which can pass 256
		.fill 	2
gpBankOldTop:									; objPtr before the insertion was reserved
		.fill 	2
gpBankLow:										; the three boundaries of the rotation
		.fill 	2
gpBankMid:
		.fill 	2
gpBankHigh:
		.fill 	2
gpBankMoveLow:									; the bottom of the range _GBShiftUp is moving
		.fill 	2
gpBankRevEnd:									; one past the last byte of the range being reversed
		.fill 	2
gpBankWalk:										; cursor into the line number table
		.fill 	2
gpBankSave:										; objPtr, held across the .fngosub walk
		.fill 	2
gpBankIdx:										; cursor into the GP.ASM fixup list
		.fill 	1
gpBankKind:										; the kind byte of the fixup in hand
		.fill 	1
gpBankShared:									; 1 in SHARED mode. Set by CompileCode before the
		.fill 	1 								; compile, because FixBranches needs it
gpBankRunPage:									; buffer page -> run page, which shared mode knows
		.fill 	1 								; up front and embedded mode does not
gpBankRunBase:									; the page the region would have run at in low memory
		.fill 	1
gpBankPages:									; pages for the bootstrap to move into the bank
		.fill 	1
gpBankTarget:									; a branch target, held across STRMakeOffset
		.fill 	2
gpBankOffset:									; ...and the offset it turned into
		.fill 	2
gpBankSideFrom:									; 1 if the branch itself is in the region
		.fill 	1
gpBankTemp:										; scratch
		.fill 	1
gpBankTemp2:									; ...and a second, for the table walks
		.fill 	1
gpBankSideTo:									; which region a branch points AT, 0 for low memory
		.fill 	1

;
;		THE REGION TABLE. One entry a GP.BANKED, in SOURCE order. Everything above is either
;		global to the compile or the WORKING COPY of whichever region GPBankRelocate has in
;		hand: the rotation happens once per region and each pass wants the same values the
;		single-region version always wanted, so the pass loads them out of here and puts the
;		results back.
;
;		EIGHT, because eight is what the bootstrap extension page's own table holds. A ninth
;		GP.BANKED is refused rather than overrunning either of them.
;
gpBankCount:									; how many regions the program has
		.fill 	1
gpBankPass:										; which one GPBankRelocate is moving
		.fill 	1
gpBankBanks:									; the bank each one named
		.fill 	GPBANK_MAXREGIONS
gpBankStarts:									; where each starts -- in the object buffer while
		.fill 	GPBANK_MAXREGIONS * 2 			; compiling, and where it ended up once its pass ran
gpBankEnds:										; ...and one past where each ends
		.fill 	GPBANK_MAXREGIONS * 2
gpBankLinesIn:									; the GP.BANKED line, for the entry bridge
		.fill 	GPBANK_MAXREGIONS * 2
gpBankLinesOut:									; the GP.ENDBANKED line, for the exit bridge
		.fill 	GPBANK_MAXREGIONS * 2
gpBankPageCounts:								; pages of each, for the bootstrap's table
		.fill 	GPBANK_MAXREGIONS
gpBankCrossings:								; what a branch crossing INTO each one is out by
		.fill 	GPBANK_MAXREGIONS
gpBankHops:										; where the walk leaves off to reach each one
		.fill 	GPBANK_MAXREGIONS * 2
		.send 	storage

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;		05/09/26		Written. Records the region only.
;		05/09/26		GPBankRelocate: the region moves to the end of the object, spliced back in
;						with two GOTOs, and every recorded address is corrected.
;		05/09/26		GP.BANKED takes the bank number. The region now moves PAST the GP.ASM pool
;						and onto a page boundary, and the object walkers hop over the pool.
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		gpcomposite.asm
;		Purpose:	COMPOSITE GP keywords -- keywords with no p-code of their own
;		Created:	19th August 2026
;		Reviewed: 	No
;		Author : 	Steven De George SR
;
; ************************************************************************************************
; ************************************************************************************************

; ************************************************************************************************
;
;		WHAT A COMPOSITE KEYWORD IS, since this file is the first of them.
;
;		A normal keyword's .def entry ends with "T", which emits its own p-code token, and a
;		handler in the runtime answers that token. That handler is linked into EVERY compiled
;		program whether it is called or not.
;
;		A composite keyword has NO "T". It emits nothing of its own; a routine in here writes a
;		sequence of tokens that ALREADY EXIST instead. So the keyword is a name for a byte
;		sequence and costs the runtime nothing at all -- no handler, no vector slot, no opcode,
;		no RT_ABI bump. Think of it as an inline function that lives in the compiler: the
;		definition never ships, only the expansion does.
;
;		IT IS THE ABSENCE OF "T" THAT MAKES IT COMPOSITE, NOT THE PRESENCE OF "X:". GP.TRIM is
;		"X:StringVariableCompile T N" and is emphatically not composite -- its X: is an ARGUMENT
;		PARSER (it insists on a plain string variable), and it still emits gp.trim and still has
;		a real handler in gpstring.asm. NOT and FN in unary.def are the shape to copy: X: with
;		no T.
;
;		WHAT CAN BE ONE. Only a keyword that is a rearrangement of things that already exist AND
;		uses each argument EXACTLY ONCE. The p-code stack has SWAP but no DUP, so an argument
;		needed twice cannot be had -- which is why GP.ENDSWITH is not in here (it wants
;		RIGHT$(a$,LEN(b$))=b$, and b$ appears twice). Anything needing a branch or a loop is out
;		for the same reason.
;
;		THE clc BEFORE EVERY rts IS NOT OPTIONAL. GeneratorExecute reads carry as "keep going";
;		return with it SET and every table element after the X: is silently dropped, including
;		the "N" that types the result. No error is raised -- the compiler just emits garbage.
;
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;						GP.CONTAINS(a$, b$) -- does b$ occur anywhere in a$ ?
;
;		Compiles to exactly what GP.INSTR(a$,b$) <> 0 compiles to, five bytes past the two string
;		expressions the table has already compiled for us:
;
;			<a$> <b$> 00 gp.instr 00 f.cmp <>
;
;		The two constants are one byte each -- PushIntegerA writes anything under 64 as a bare
;		byte -- and gp.instr is unshifted, so nothing here costs two.
;
;		The f.cmp/<> PAIR is how a comparison between numbers is spelt in p-code; f.cmp leaves
;		255/0/1 and the comparator reads it. CompileCaseTest in commands/select.asm emits the
;		same pair by hand for the same reason, and the expression compiler itself emits it for
;		any "=" you write (evaluate/expression.asm).
;
;		CASE SENSITIVE, because gp.instr compares raw bytes. GP.COMP is the case folding one and
;		is a whole-string compare, not a search, so it cannot serve here; a case insensitive
;		search would need a folding loop, which is real machine code and not a composite.
;
;		AN EMPTY NEEDLE IS FALSE. gp.instr returns 0 for a zero length needle ("an empty needle
;		never matches", gpstring.asm), so GP.CONTAINS(a$,"") is 0 even though every string
;		trivially contains "". Correcting it needs a branch, which a composite cannot express.
;
; ************************************************************************************************

GPContainsCompile:
		lda 	#0 							; gp.instr's optional start -- 0 is "from the beginning"
		jsr 	PushIntegerA
		.keyword PCD_GPCMD_INSTR 			; -> the 1-based position, or 0 if it is not there
		;
		lda 	#0 							; found ANYWHERE at all is "the position is not zero"
		jsr 	PushIntegerA
		.keyword PCD_FCMD_CMP 				; compare the two numbers -> 255/0/1 ...
		.keyword PCD_LESSGREATER 			; ... which "<>" turns into BASIC's -1 or 0
		clc 								; carry CLEAR or the "N" after the X: is dropped
		rts


; ************************************************************************************************
;
;			GP.HIBYTE(n) / GP.LOBYTE(n) -- an address split into the two bytes a 6502 takes
;
;		A 6502 address is sixteen bits and everything that consumes one -- GP.CALL's registers,
;		VERA's $9F20/$9F21 -- takes eight at a time. So every address that leaves BASIC for machine
;		code gets split, and GP.STRPTR / GP.ARRPTR exist precisely to hand one over.
;
;			GP.HIBYTE(n)  =  INT(n / 256)      which 256 byte page
;			GP.LOBYTE(n)  =  MOD(n, 256)       offset within it
;
;		WHY THESE EARN A KEYWORD when the expressions are short. The obvious low byte, "n AND 255",
;		is a LIVE BUG in GPC: AND is 16 bit SIGNED, and every address worth splitting is above
;		32767 -- the string heap always is -- so it raises OUT OF RANGE rather than masking. The
;		tree currently writes the long form out by hand in four places, each with a warning comment
;		nailed beside it (ARRAYS.EXP.BL, BMX.INC.BL, MENUVERT.INC.BL, GPB.INC.BL). A keyword makes
;		the correct form the short one and the wrong form unreachable.
;
;		MOD rather than the subtraction the docs currently recommend, because MOD uses the whole
;		argument ONCE. "n - INT(n/256)*256" needs it twice, and a composite has no DUP -- so the
;		spelling is not a preference here, it is the only one that fits. Measured 2026-08-19:
;		MOD(1000000,256) = 64 and MOD(40693,256) = 245, agreeing with the subtraction form, so
;		UnaryMOD's Int32Divide really is clear of the 16 bit signed path AND takes.
;
;		DOMAIN is 0..65535, which is every address on this machine. A negative argument is not
;		rejected: INT rounds toward minus infinity while MOD works on magnitudes, so the two would
;		stop being a matched pair. Nothing that produces an address can produce a negative.
;
; ************************************************************************************************

GPHiByteCompile:
		jsr 	GPPush256
		.keyword PCD_DIVIDE
		.keyword PCD_INT 					; INT after the divide, not a shift -- n may be a float
		clc 								; carry CLEAR or the "N" after the X: is dropped
		rts

GPLoByteCompile:
		jsr 	GPPush256
		.keyword PCD_MOD 					; MOD(n,256): dividend pushed first, divisor on top
		clc
		rts

;
;		256 will not fit the one byte constant path, so PushIntegerYA emits a two byte .word --
;		the same shape OptionalColourCompile uses for its 256 sentinel.
;
GPPush256:
		lda 	#0
		ldy 	#1
		jmp 	PushIntegerYA


; ************************************************************************************************
;
;								GP.ISEMPTY(a$) -- is the string zero length ?
;
;			<a$> len 0 f.cmp =        four bytes past the string expression
;
;		READABILITY ONLY, and it is worth saying so plainly because the obvious guess is that a
;		keyword must be faster. It is not: this compiles to exactly what LEN(a$)=0 compiles to, and
;		IF a$="" costs about the same again -- CommandPushS points a literal INTO the p-code, so
;		even the empty string literal allocates nothing. All three are the same price. This one just
;		states the question rather than leaving the reader to infer it from the shape of a test.
;
;		Returns BASIC's -1 / 0, like every other comparison in the language.
;
; ************************************************************************************************

GPIsEmptyCompile:
		.keyword PCD_LEN
		lda 	#0
		jsr 	PushIntegerA
		.keyword PCD_FCMD_CMP 				; the number comparison pair, as GP.CONTAINS above
		.keyword PCD_EQUAL
		clc 								; carry CLEAR or the "N" after the X: is dropped
		rts

		.send 	code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;		19/08/26		Written.
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		gpif.asm
;		Purpose:	GP.IF / GP.ELSEIF / GP.ELSE / GP.ENDIF
;		Created:	30th August 2026
;		Reviewed: 	No
;		Author : 	Steven De George SR
;
; ************************************************************************************************
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;		GP.IF <expr> THEN
;		GP.ELSEIF <expr> THEN
;		GP.ELSE
;		GP.ENDIF
;
;		A block IF. Each keyword is ALONE ON ITS LINE -- there is no single line form, and the
;		THEN is required, so "GP.IF X > 5 THEN PRINT" is rejected rather than quietly opening a
;		block that swallows every line until the next GP.ENDIF.
;
;		Lowering, for GP.IF a / GP.ELSEIF b / GP.ELSE / GP.ENDIF:
;
;			<a> gp.if .ifnext -> one past the .ifelse below
;			<body>
;			.ifelse -> gp.endif       <b> .ifnext -> one past the next .ifelse
;			<body>
;			.ifelse -> gp.endif
;			<body>
;			gp.endif                  a marker, nothing more; there is no frame to close
;
;		NO STACK FRAME, unlike GP.SELECT. The frame there is forced by new.line resetting the
;		number stack at every source line, because the selector has to survive to the next line.
;		A condition is evaluated and consumed by its .ifnext on the SAME line, so there is
;		nothing to preserve -- which is why the whole construct costs 12 runtime bytes and none
;		of them are code. .ifnext runs the .goto.z handler and .ifelse runs the .goto handler;
;		only FixBranches tells them from .casenext and .caseend.
;
;		GP.ELSEIF IS WHAT FORCES gp.if TO EXIST. Without it FixBranches could count nesting on
;		.ifnext against gp.endif, one to one, and the marker would not be needed. But GP.ELSEIF
;		emits .ifelse and then its OWN <cond> .ifnext, which would inflate the depth of a scan
;		already in flight and send it past its own gp.endif. So depth is counted on a marker
;		GP.ELSEIF does not emit -- and note below that it deliberately writes no gp.if.
;
;		ALL FOUR DISARM deferErrors FIRST. A statement that fails with a SYNTAX error while the
;		deferral is armed is rolled back and replaced with a runtime throw-stub -- which for a
;		block opener means its gp.if vanishes while the GP.ENDIF on a later line still compiles
;		and still emits. The block is left with a closer and no opener, and an ENCLOSING IF's
;		scan then counts one extra close and resolves its branches to the wrong place, silently.
;		Three bytes of stz buys a hard, correctly-named error instead.
;
;		All four MUST return carry CLEAR. A .def helper returning carry set makes the generator
;		silently drop every table element after it, with no error and no clue.
;
; ************************************************************************************************

CommandIfCompile:
		stz 	deferErrors 				; a block opener must never defer -- see the header
		jsr 	CompileExpressionAt0 		; the condition
		and 	#NSSTypeMask
		cmp 	#NSSIFloat
		bne 	IfFailType
		jsr 	IfRequireThenEOL
		lda 	#PCD_GPCMD_IF 				; the marker FixBranches counts nesting on
		jsr 	WriteCodeByte
		lda 	#PCD_CMD_IFNEXT 			; false -> the next alternative, or the gp.endif
		jsr 	WriteCodeByte
		jmp 	IfWritePlaceholder

;
;		GP.ELSEIF is a closer and an opener in one: the .ifelse leaves the body above, then the
;		test opens the next. It writes NO gp.if -- an ELSEIF does not deepen the nesting, it
;		continues the chain the GP.IF started, and the scans depend on that.
;
CommandElseIfCompile:
		stz 	deferErrors
		lda 	#PCD_CMD_IFELSE 			; out of the body above, to the gp.endif
		jsr 	WriteCodeByte
		jsr 	IfWritePlaceholder
		jsr 	CompileExpressionAt0
		and 	#NSSTypeMask
		cmp 	#NSSIFloat
		bne 	IfFailType
		jsr 	IfRequireThenEOL
		lda 	#PCD_CMD_IFNEXT
		jsr 	WriteCodeByte
		jmp 	IfWritePlaceholder

CommandElseCompile:
		stz 	deferErrors
		lda 	#PCD_CMD_IFELSE
		jsr 	WriteCodeByte
		jsr 	IfWritePlaceholder
		jmp 	IfRequireEOL

;
;		GP.ENDIF is a marker and nothing else. Every .ifnext that ran out of alternatives lands
;		ON it and every .ifelse lands ON it, which costs nothing because it does nothing.
;
CommandEndIfCompile:
		stz 	deferErrors
		lda 	#PCD_GPCMD_ENDIF
		jsr 	WriteCodeByte
		jmp 	IfRequireEOL

;
;		THEN is a ROM keyword ($a7), so BASLOAD tokenises it with no GP keyword slot spent and it
;		emits no p-code of its own. Requiring it costs the five bytes CommandIF already spends.
;
IfRequireThenEOL:
		lda 	#C64_THEN
		jsr 	CheckNextA
;
;		Nothing may follow. This is the check that makes the single line form illegal rather than
;		merely undefined, and with deferErrors already disarmed it aborts the compile instead of
;		becoming a throw-stub.
;
IfRequireEOL:
		jsr 	LookNextNonSpace
		beq 	_IREDone
		.error_syntax
_IREDone:
		rts

;
;		Two placeholder bytes. The value is never read: FixBranches overwrites both
;		unconditionally, and errors out rather than leaving them if it cannot resolve the branch.
;
IfWritePlaceholder:
		lda 	#0
		jsr 	WriteCodeByte
		lda 	#0
		jsr 	WriteCodeByte
		clc
		rts

IfFailType:
		.error_type

		.send code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;		30/08/26		Written.
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		if.asm
;		Purpose:	If command
;		Created:	19th April 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;											IF
;
; ************************************************************************************************

CommandIF: 		
		jsr 	LookNextNonSpace 			; what follows the tests ?
		cmp 	#C64_GOTO 					; IF .. GOTO
		beq 	_CIGoto
		;
		lda 	#C64_THEN 					; should be THEN
		jsr 	CheckNextA
		;
		jsr 	LookNextNonSpace 			; THEN <number>
		jsr 	CharIsDigit
		bcs 	_CIGoto2
		bra 	CompileGotoEOL

_CIGoto:	
		jsr 	GetNext 					
_CIGoto2:		
		lda 	#PCD_CMD_GOTOCMD_NZ
		jsr 	CompileBranchCommand
		rts
		
CompileGotoEOL: 							; compile GOTOZ <next line>
		lda 	#PCD_CMD_GOTOCMD_Z
		jsr 	WriteCodeByte
		jsr 	GetLineNumber 				; Get the current line number => YA
		inc 	a 							; and branch to +1
		bne 	_CGENoCarry
		iny
_CGENoCarry:		
		jsr 	WriteCodeByte
		tya
		jsr 	WriteCodeByte
		rts

		.send code


; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		input.asm
;		Purpose:	INPUT command
;		Created:	1st May 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;											INPUT
;
; ************************************************************************************************

CommandINPUT:
		jsr 	LookNextNonSpace 			; check for "
		cmp 	#'"'
		bne 	CommandINPUTStream
		jsr 	CompileExpressionAt0
		.keyword PCD_PRINTCMD_S
		jsr 	GetNextNonSpace 			; followed by ; or ,
		cmp 	#","
		beq 	CommandINPUTStream
		cmp 	#";"
		beq 	CommandINPUTStream
		.error_syntax
		
CommandINPUTStream:
		.keyword PCD_INPUTCMD_START 		; new INPUT.
		ldx 	#PCD_INPUT 					; do READ with Data from INPUT
		ldy 	#PCD_INPUTDOLLAR
		jmp 	CommandReadInputCommon

		.send code

; ************************************************************************************************
;
;		Notes:
;			INPUT has an optional prompt ; INPUT# skips this code <string> print.s
;			Do the actual input.
;			Ignore blank lines.
; 			Behaves like READ in that it will grab data read , store keep going until have
; 			everything, use of , and "" etc.
;
; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		let.asm
;		Purpose:	Assignment statement
;		Created:	18th April 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;										Assignment statement
;
; ************************************************************************************************

CommandLET:
		jsr 	GetNextNonSpace 			; get the first character
CommandLETHaveFirst:
		jsr 	GetReferenceTerm 			; identify variable to assign to
		phx 								; save target on the stack.
		phy
		pha
		lda 	#C64_EQUAL 					; check next is =
		jsr 	CheckNextA
		jsr 	CompileExpressionAt0 		; evaluate the RHS.

		sta 	zTemp0 						; save type returned
		pla 								; get type of assignment
		pha
		eor 	zTemp0 						; compare using EOR
		and 	#NSSTypeMask 				; so we can mask type as we only need n/s
		bne 	_CLType

		pla 								; restore and compile save code
		ply
		plx

		cpy 	#$80 						; is it TI = xxxxx
		beq 	_CLTINumber
		cpy 	#$C0 						; is it TI$ = "xxxxx"
		beq 	_CLTIString
		sec
		jsr		GetSetVariable
		rts

_CLTINumber:
		.keyword PCD_TICMD_WRITE
		rts
_CLTIString:
		.keyword PCD_TIDOLLARCMD_WRITE
		rts
		
_CLType:
		.error_type

		.send code


; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		linput.asm
;		Purpose:	LINPUT, LINPUT# and BINPUT#
;		Created:	14th July 2026
;		Reviewed: 	No
;
; ************************************************************************************************
; ************************************************************************************************
;
;		The emitted code has to come out in this order:
;
;			push the delimiter (or the count)		<- the P-code reads it from S[X]
;			[linput] / [binput]						<- and replaces it with the string
;			store into the variable
;
;		but the SOURCE reads the other way round -- "LINPUT# 1,A$,34" names the variable first and
;		the delimiter last. GetReferenceTerm emits nothing, so the variable can be parsed early and
;		its store emitted late; what it DOES do is hand back the address in X and Y, which is what
;		GetSetVariable wants. Compiling the delimiter expression in between will certainly not leave
;		X and Y alone, so the address is parked on the 6502 stack across it.
;
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;										LINPUT <var$>
;
; ************************************************************************************************

CommandLINPUT:
		jsr 	LinputGetVariable 			; A = type, XY = address; nothing emitted yet
		pha
		phx
		phy
		lda 	#13 						; the keyboard form always ends at a carriage return
		jsr 	PushIntegerA
		bra 	LinputEmit

; ************************************************************************************************
;
;					LINPUT# <n>,<var$>[,<delimiter>]
;
;		The channel and its comma have already been eaten by the C: prefix (ChannelPrefix).
;
; ************************************************************************************************

CommandLINPUTStream:
		jsr 	LinputGetVariable
		pha
		phx
		phy
		jsr 	LookNextNonSpace 			; an explicit delimiter ?
		cmp 	#","
		bne 	_CLISDefault
		jsr 	GetNext 					; consume the comma
		jsr 	CompileExpressionAt0
		and 	#NSSTypeMask
		cmp 	#NSSIFloat
		bne 	LinputType
		bra 	LinputEmit
_CLISDefault:
		lda 	#13 						; "the delimiter of a line by default is 13"
		jsr 	PushIntegerA

LinputEmit: 								; global, not a cheap local: LINPUT branches in from its
		.keyword PCD_LINPUT 				; own scope, and _locals do not cross one
LinputStore:
		ply 								; the variable was parked before the delimiter was
		plx 								; compiled; take it back and write the store
		pla
		sec
		jsr 	GetSetVariable
		rts

; ************************************************************************************************
;
;						BINPUT# <n>,<var$>,<len>
;
;		The length is not optional, so there is no default to fall back on.
;
; ************************************************************************************************

CommandBINPUTStream:
		jsr 	LinputGetVariable
		pha
		phx
		phy
		jsr 	GetNextNonSpace
		cmp 	#","
		bne 	LinputSyntax
		jsr 	CompileExpressionAt0
		and 	#NSSTypeMask
		cmp 	#NSSIFloat
		bne 	LinputType
		.keyword PCD_BINPUT
		bra 	LinputStore

; ************************************************************************************************
;
;		Parse the target variable. All three of these read into a string and nothing else.
;
; ************************************************************************************************

LinputGetVariable:
		jsr 	GetNextNonSpace
		jsr 	CharIsAlpha
		bcc 	LinputSyntax
		jsr 	GetReferenceTerm 			; A = type, XY = the variable's address
		pha
		and 	#NSSTypeMask
		cmp 	#NSSString
		bne 	LinputType
		pla 								; leaves XY alone, which is the whole point
		rts

LinputType:
		.error_type

LinputSyntax:
		.error_syntax

		.send code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		mark_line.asm
;		Purpose:	Line Number Tracking
;		Created:	15th April 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;								Store current position, line YA
;
; ************************************************************************************************

STRMarkLine:
		pha
		sec 								; allocate 4 bytes (line #,address)
		lda 	lineNumberTable 			; and copy to zTemp0
		sbc 	#4
		sta 	lineNumberTable
		sta 	zTemp0
		lda 	lineNumberTable+1
		sbc 	#0
		sta 	lineNumberTable+1
		sta 	zTemp0+1

		;
		;		Still inside the window? This table grows DOWN from CompilerWorkspaceEnd, and
		;		without a test it was free to walk out of the bottom of the bank in silence.
		;		(A is free here: the caller's value is on the stack until the pla below, and
		;		ExitCompiler restores SP, so raising with it still pushed is fine.)
		;
		;		THIS USED TO TEST AGAINST variableListEnd. Both tables lived in one 8K bank and
		;		grew towards each other, so the real limit was the SUM of the two -- and
		;		samples/editor had reached 7,981 of 8,192 with 1,461 lines and 356 variables.
		;		Fifty-two more lines and this test fired PROGRAM TOO BIG with a THIRD of the
		;		object budget unused. One bank each (x16_storage.inc) makes the limit this
		;		table's own window, which is 2,048 lines.
		;
		lda 	lineNumberTable+1 			; the entry is 4 bytes AT the pointer and the window
		cmp 	compilerStartHigh 			; starts on a page boundary, so the high byte is the
		bcs 	_SMLRoom 					; whole test -- any offset within that page is inside.
		.error_toobig
_SMLRoom:

		.storage_access
		pla
		sta 	(zTemp0) 					; line # save it in +0,+1
		tya
		ldy 	#1
		sta 	(zTemp0),y
		;
		lda 	objPtr 						; save current address in +2,+3
		iny
		sta 	(zTemp0),y
		lda 	objPtr+1
		iny
		sta 	(zTemp0),y

		.storage_release
		rts

; ************************************************************************************************
;
;				Line number YA - find in table, return address YA 
;				
;				If FOUND: of the matching line, with Carry Clear.
;				If NOT FOUND : of the previous line (e.g. next code line), with Carry Set.
;
; ************************************************************************************************

STRFindLine:
		.storage_access

		sta 	zTemp0 						; zTemp0 line number being searched
		sty 	zTemp0+1
		
		lda 	compilerEndHigh 			; work backwards through table
		sta 	zTemp1+1
		stz 	zTemp1

_STRSearch:
		jsr 	_STRPrevLine 				; look at previous record.

		ldy 	#1
		lda 	(zTemp1) 					; check table line # >= target
		cmp 	zTemp0
		lda 	(zTemp1),y
		sbc 	zTemp0+1
		bcs 	_STRFound 					; >=
_STRNext: 									; next table entry.
		ldy 	#1 							; should not be required !
		lda 	(zTemp1),y
		cmp 	#$FF
		bne 	_STRSearch
		.storage_release 					; the only escape from inside a storage window -- close
		.error_internal 					; it, or the error handler runs with the wrong RAM bank

_STRFound:
		lda 	(zTemp1) 					; set A = 0 if the same, 0 if different.
		eor 	zTemp0
		bne 	_STRDifferent
		lda 	(zTemp1)
		eor 	zTemp0
		beq 	_STROut 					; if zero, exit with A = 0 and correct line.

_STRDifferent:
		lda 	#$FF 						
_STROut:
		clc  								; set carry if different, e.g. > rather than >=
		adc 	#255 				
		php
		iny 								; address into YA
		lda 	(zTemp1),y
		pha
		iny
		lda 	(zTemp1),y
		tay
		pla	
		.storage_release
		plp	
		rts

_STRPrevLine:
		sec 								; move backwards one entry.
		lda 	zTemp1
		sbc 	#4
		sta 	zTemp1
		lda 	zTemp1+1
		sbc 	#0
		sta 	zTemp1+1
		rts
; ************************************************************************************************
;
;								Make position X:YA to Offset X:YA
;
; ************************************************************************************************

STRMakeOffset:
		clc 								; borrow 1
		sbc 	objPtr
		pha
		tya
		sbc 	objPtr+1
		tay
		pla
		rts
		
		.send code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		nex.asm
;		Purpose:	NEXT compile
;		Created:	20th April 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;										Compile NEXT command
;
;								   Creates [Reference|$FFFF] NEXT
;
; ************************************************************************************************

CommandNEXT: 
		;
		;		NEXT [variable]
		;
		jsr 	LookNextNonSpace 			; first letter of index variable, should be.
		jsr 	CharIsAlpha 				; if not alpha , error
		bcc 	_CNNoReferenceGiven
		jsr 	GetNext
		jsr 	GetReferenceTerm 			; figure out the reference.
		txa 								; reference in YA
		jsr 	PushIntegerYA 				; write it out.
		bra 	_CNParametersDone
_CNNoReferenceGiven:
		lda 	#255 						; write out -1 no
		tay
		jsr 	PushIntegerYA 				; write it out.
_CNParametersDone:
		lda 	#PCD_NEXT  					; compile FOR word.
		jsr 	WriteCodeByte

		jsr 	LookNextNonSpace 			; look for , 
		cmp 	#","
		bne 	_CNExit
		jsr 	GetNext 					; consume ,
		bra 	CommandNEXT 				; and go round.

_CNExit:
		rts

		.send code


; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		on.asm
;		Purpose:	ON compiler
;		Created:	21st April 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;											Compile ON
;
; ************************************************************************************************

CommandON:
		jsr 	GetNextNonSpace 			; GOTO / GOSUB must follow
		pha 								; save on stack

		ldx 	#PCD_CMD_GOTO
		cmp 	#C64_GOTO 					; must be GOTO/GOSUB
		beq 	_COCreateLoop
		ldx 	#PCD_CMD_GOSUB
		cmp 	#C64_GOSUB
		beq 	_COCreateLoop
		.error_syntax

_COCreateLoop:
		txa 								; compile a goto/gosub somewhere
		phx
		jsr 	CompileBranchCommand		
		plx
		jsr 	LookNextNonSpace			; ',' follows
		cmp 	#"," 						
		bne 	_COComplete 				; if so, more line numbers
		lda 	#PCD_MOREON 				; ON extends.
		jsr 	WriteCodeByte
		jsr 	GetNext
		bra 	_COCreateLoop

_COComplete:
		pla 								; throw GOTO/GOSUB
		rts

		.send code


; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		parsenumber.asm
;		Purpose:	Parse numeric constant
;		Created:	16th April 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;				Parse numeric constant into stack level 0, first char is in A
;				   Return CS if legitimate 16 bit +ve int with value in YA
;
; ************************************************************************************************

ParseConstant:
		ldx 	#0 
		jsr 	FloatEncodeStart 			; send first
_ParseLoop:
		jsr 	LookNext 					; send subsequent
		jsr 	FloatEncodeContinue
		bcc 	_ParseDone
		jsr 	GetNext 					; consume it
		bra 	_ParseLoop

_ParseDone:
		lda 	NSStatus,x 					; shouldn't be -ve ....
		and 	#$80
		ora 	NSExponent,x 				; 16 bit int check
		ora 	NSMantissa2,x
		ora 	NSMantissa3,x
		clc
		bne 	_ParseExit 					; exit with CC if need float to compile

		lda 	NSMantissa0,x 				; read into YA.
		ldy		NSMantissa1,x
		sec
_ParseExit:		
		rts		





		.send code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		print.asm
;		Purpose:	Print compilation
;		Created:	19th April 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;						  					Print Command
;
; ************************************************************************************************

CommandPRINT:
		jsr 	LookNextNonSpace			; what follows ?
		cmp 	#";" 						; semicolon, check end of command
		beq 	_CPCheckEnd
		cmp 	#"," 						; , TAB and check end of command
		beq 	_CPTabCheckEnd	
		jsr 	_CPAtEnd 					; check for : and EOL
		bcs 	_CPExitCR 					; exit with CR
		;
		cmp 	#C64_TABLB 					; TAB( found
		beq 	_CPHaveTabSpcFunc
		cmp 	#C64_SPCLB 					; SPC( found
		beq 	_CPHaveTabSpcFunc
		;
		jsr 	CompileExpressionAt0 		; so it is something to print
		ldx 	#PCD_PRINTCMD_S
		and 	#NSSString 					; if string
		bne 	_CPOut
		ldx 	#PCD_PRINTCMD_N
_CPOut:
		txa 								; print that thing
		jsr 	WriteCodeByte		
		bra 	CommandPRINT 				; and loop round/
		;
		;		, comes here
		;
_CPTabCheckEnd:
		lda 	#PCD_PRINTCMD_TAB 			; , next tab stop
		jsr 	WriteCodeByte
		;
		;		; comes here and ,  - if end command after no CR.
		;
_CPCheckEnd:
		jsr 	GetNext 					; consume it.
		jsr 	LookNextNonSpace 			; what follows ?
		jsr 	_CPAtEnd 					; reached end
		bcc 	CommandPRINT 				; no, loop back
		rts
		;
		;		: and EOL come here.
		;
_CPExitCR:
		lda 	#13 						; code to print CR
		jsr 	PushIntegerA		
		lda 	#PCD_PRINTCMD_CHR
		jsr 	WriteCodeByte
		rts
		;
		;		TAB( and SPC( come here
		;
_CPHaveTabSpcFunc:
		jsr 	GetNextNonSpace 			; get the TAB( or SPC(
		pha 								; save it.
		jsr 	CompileExpressionAt0 		; compile expression, the TAB or SPC size.
		and 	#NSSTypeMask 				; check number.
		cmp  	#NSSIFloat
		bne 	_CPType
		jsr 	GetNextNonSpace 			; get next skipping spaces
		cmp 	#")"						; check closing bracket.
		bne 	_CPSyntax	
		pla
		cmp 	#C64_TABLB 					; output SPC or POS command accordingly.
		beq 	_CPIsTabFunc
		lda 	#PCD_PRINTCMD_SPC
		jsr 	WriteCodeByte
		bra 	CommandPRINT
_CPIsTabFunc:
		lda 	#PCD_PRINTCMD_POS
		jsr 	WriteCodeByte
		bra 	CommandPRINT

_CPSyntax:		
		.error_syntax

_CPType:
		.error_type
;
;		Check ending character, is it EOS or :
;
_CPAtEnd:
		cmp 	#0
		beq 	_CPIsEnd
		cmp 	#":"
		beq 	_CPIsEnd
		clc
		rts
_CPIsEnd:
		sec
		rts

		.send code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		read.asm
;		Purpose:	Compile READ Statements
;		Created:	22nd April 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;										Compile a READ
;
; ************************************************************************************************

CommandREAD:
		ldx 	#PCD_READ
		ldy 	#PCD_READDOLLAR
;
;		Code shared by READ and INPUT
;
CommandReadInputCommon:
		stx 	numberPCode
		sty 	stringPCode
_CRLoop:				
		jsr 	GetNextNonSpace 			; first char of identifier
		jsr 	CharIsAlpha 				; check A-Z
		bcc 	_CRSyntax
		jsr 	GetReferenceTerm 			; get the variable.
		pha 								; save type.

		and 	#NSSTypeMask 				; is it a string ?
		cmp 	#NSSString
		beq 	_CRString
		lda 	numberPCode 				; output read/input
		bra 	_CRHaveType
_CRString:		
		lda 	stringPCode					; output read$/input$
_CRHaveType:		
		jsr 	WriteCodeByte 				; so we have one typed data item.
		pla 								; restore type
		sec  								; write update code.
		jsr 	GetSetVariable
		jsr 	LookNextNonSpace 			; , follows ?
		cmp 	#","
		bne 	_CRExit 					; if not, end of READ.
		jsr 	GetNext 					; consume comma
		bra 	_CRLoop 					; keep going
_CRExit:		
		rts		
_CRSyntax:
		.error_syntax

		.send code

		.section storage
numberPCode:	
		.fill 	1
stringPCode:
		.fill 	1
		.send storage

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		readwrite.asm
;		Purpose:	Generate code to read/write variables
;		Created:	18th April 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;					On entry YX is the address and A the type data (bits 7..5)
;						CS => generate write code, CC => generate read code
;
; ************************************************************************************************

GetSetVariable:
		php 								; save direction on stack
		cpy 	#$00
		bmi 	_GSVReadWriteSpecial
		cmp 	#$00
		bmi 	_GSVArray
		;
		; 		64-79 is float, 80-95 is integer, 96-111 is string. So we multiply the
		;		type bits 5 & 6 byte 16 - but they are already multiplied by 32, so
		;
		and 	#NSSTypeMask+NSSIInt16 		; get type bits
		lsr 	a 							; divide by 2
		ora 	#64 						; and set bit 6.
		;
		plp
		bcc 	_GSVNotWrite
		ora 	#8  						; set bit 3 if it is write.
_GSVNotWrite:
		sta 	zTemp0
		;
		tya 	 							; shift X/Y right as the address stored is halved
		lsr 	a
		tay 	
		txa 
		ror 	a
		tax
		;
		tya 								; lower 3 bits of YX are ORed into the opcode
		ora 	zTemp0 						; which is the first byte of the opcode
		jsr 	WriteCodeByte
		;
		txa 								; and the lower 8 bits of YX are the second byte
		jsr 	WriteCodeByte
		rts
		;
		;		Special read/writes
		;
		;
		;		A reserved name. FindVariable handed back a fake address with bit 7 of Y set, and
		;		the high byte says which one: $80 = TI, $C0 = TI$, $A0 = ST. All three are read
		;		only through this path -- LET has its own code for writing TI and TI$, and ST is
		;		the KERNAL's, so writing it is a syntax error.
		;
_GSVReadWriteSpecial:
		plp
		bcs 	_GSVSyntax
		;
		cpy 	#$C0 						; TI$ ?
		beq 	_GSVRWString
		cpy 	#$A0 						; ST ?
		beq 	_GSVRWStatus
		.keyword PCD_TI
		rts
_GSVRWString:
		.keyword PCD_TIDOLLAR
		rts
_GSVRWStatus:
		.keyword PCD_ST
		rts

_GSVSyntax:
		.error_syntax
		;
		;		For arrays use the indirection @ %@ $@ ! %! $!
		;
_GSVArray:
		and 	#NSSTypeMask+NSSIInt16 		; mask out 2 bits of type data
		lsr 	a		 					; shift from 5,6 to 0,1
		lsr 	a		
		lsr 	a		
		lsr 	a		
		lsr 	a				
		plp 								; if writing array then set bit 2.
		bcc 	_GSVANotWrite
		ora 	#4
_GSVANotWrite:		
		ora 	#$78 						; make a valid opcode.
		jsr 	WriteCodeByte 				; and write it out
		rts

		.send code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		refterm.asm
;		Purpose:	Get reference term
;		Created:	25th April 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

; ************************************************************************************************
;
;		On entry, A contains the first character.  Extract the variable name and locate it
;		creating if necessary, returning offset in YX, type in A.
;
; ************************************************************************************************

		.section code

GetReferenceTerm:
		jsr 	ExtractVariableName 		; get name & type info
		cpx 	#0 							; check for array handler
		bmi 	_GRTArray
		phx 								; save type on stack
		jsr 	FindVariable 				; find it
		bcs 	_GRTNoCreate 				; create if required.
		jsr 	CreateVariableRecord 		; create a variable.
		jsr 	AllocateBytesForType 		; allocate memory for it
_GRTNoCreate:		
		pla 								; get type back, strip out type information.
		and 	#NSSTypeMask+NSSIInt16
		rts		
	
_GRTArray:
		phx 								; save type information (also = the name if we must create)
		jsr 	FindVariable 				; CS: found, base address in YX. CC: unknown -> YX = name.
		lda 	#0 							; flag: 0 = the array already exists (LDA leaves carry alone)
		bcs 	_GRTKnown
		lda 	#$FF 						; $FF = undimensioned, create it once we know how many indices
_GRTKnown:
		pha 								; save that flag, and the name/address, over OutputIndexGroup
		phx
		phy
		;
		;		The NC form: subscripts only, no count word after them. How many there were comes
		;		back in IndexCount, and only a reference with two or more needs that count pushed
		;		-- the single-subscript case, which is very nearly all of them, uses the fused
		;		PCD_ARRAY1 below and that keyword already knows the count is one.
		;
		jsr 	OutputIndexGroupNC 			; compile the subscripts; IndexCount = how many
		lda 	IndexCount 					; take our own copy now: GetSetVariable and
		sta 	refIndexCount 				; RegisterImplicitArray both run before we read it back
		cmp 	#2
		bcc 	_GRTNoCountWord 			; one subscript -> the fused keyword needs no count
		jsr 	PushIntegerA 				; two or more -> PCD_ARRAY reads a count word
_GRTNoCountWord:
		ply 								; restore name/address into YX
		plx
		pla 								; and the create flag
		beq 	_GRTResolved 				; existing array -> YX is already its base address
		;
		;		Undimensioned array. Interpreted BASIC would auto-create it here as 0..10 in each
		;		dimension. We now know the dimension count (IndexCount), so register it -- the
		;		prologue emitted at the start of the program dimensions it before any code runs.
		;
		jsr 	RegisterImplicitArray 		; create the record now, returning its slot address in YX
_GRTResolved:
		lda 	#NSSIFloat+NSSIInt16 		; pretend it is an int16 reference.
		clc
		jsr 	GetSetVariable 				; load the address of the array structure.
		;
		;		One subscript takes the fused keyword. It saves the count word -- a whole p-code
		;		dispatch to push it, and a GetInteger8Bit in the runtime to read it back -- on an
		;		access whose count the compiler knew all along.
		;
		lda 	refIndexCount
		cmp 	#1
		bne 	_GRTManyIndices
		.keyword PCD_ARRAY1 				; convert that to an offset, count implicitly 1
		bra 	_GRTIndexed
_GRTManyIndices:
		.keyword PCD_ARRAY 					; convert that to an offset, count read off the stack
_GRTIndexed:
		pla 								; and the type data into A
		and 	#NSSTypeMask+NSSIInt16
		ora 	#$80 						; with the array flag set.
		rts

; ************************************************************************************************
;
;		Register an undimensioned array so the implicit-DIM prologue can create it. On entry YX
;		is the (array) name and IndexCount is the number of indices in the reference that
;		discovered it, which becomes its dimension count. Creates the variable record and its
;		pointer slot now (so this reference and later ones resolve normally) and records the slot
;		address, element type and dimension count for EmitImplicitDims. Returns YX = slot address.
;		Falls back to the old "unknown array" error only if more than 32 need dimensioning.
;
; ************************************************************************************************

RegisterImplicitArray:
		lda 	implicitDimCount 			; capacity check
		cmp 	#32
		bcs 	_RIAFull
		txa 								; element type comes from the name's type bits
		and 	#NSSTypeMask+NSSIInt16
		sta 	implicitDimType
		jsr 	CreateVariableRecord 		; make the record (YX = name) -> YX = slot address
		stx 	implicitDimAddr
		sty 	implicitDimAddr+1
		lda 	implicitDimType
		jsr 	AllocateBytesForType 		; reserve the pointer slot
		lda 	implicitDimCount 			; append a list entry at count*4
		asl 	a
		asl 	a
		tax
		lda 	implicitDimAddr
		sta 	implicitDimList+0,x
		lda 	implicitDimAddr+1
		sta 	implicitDimList+1,x
		lda 	implicitDimType
		sta 	implicitDimList+2,x
		lda 	IndexCount 					; dimension count (>= 1 for a real reference)
		bne 	_RIAHaveCount
		lda 	#1
_RIAHaveCount:
		sta 	implicitDimList+3,x
		inc 	implicitDimCount
		ldx 	implicitDimAddr 			; return the slot address in YX for GetSetVariable
		ldy 	implicitDimAddr+1
		rts
_RIAFull:
		.error_undeclared

; ************************************************************************************************
;
;		An explicit DIM found that its array already has a record. Decide whether that record was
;		created by RegisterImplicitArray (i.e. a reference auto-registered the array before this
;		DIM in source order) rather than by a real earlier DIM. On entry YX is the array's slot
;		address, exactly as FindVariable returned it. If a live list entry matches that address,
;		tombstone it -- set its dimension count to 0 so EmitImplicitDims emits nothing for it --
;		and return CS with YX preserved, so the DIM dimensions the array for real at the bounds
;		the programmer wrote. If nothing matches, return CC: this is a genuine re-DIM.
;
; ************************************************************************************************

TakeOverImplicitArray:
		stx 	zTemp0 						; remember the slot address to match, and to hand back
		sty 	zTemp0+1
		ldy 	implicitDimCount 			; entries to scan
		beq 	_TOIANo 					; none registered -> cannot be an implicit array
		ldx 	#0 							; byte offset into the 4-bytes-per-entry list
_TOIALoop:
		lda 	implicitDimList+3,x 		; dimension count; 0 = already tombstoned, skip it
		beq 	_TOIANext
		lda 	implicitDimList+0,x 		; match the slot address, low then high
		cmp 	zTemp0
		bne 	_TOIANext
		lda 	implicitDimList+1,x
		cmp 	zTemp0+1
		bne 	_TOIANext
		lda 	#0 							; found it -> tombstone so the prologue skips this array
		sta 	implicitDimList+3,x
		ldx 	zTemp0 						; hand the slot address back in YX
		ldy 	zTemp0+1
		sec 								; CS = taken over
		rts
_TOIANext:
		inx 								; step over this 4-byte entry
		inx
		inx
		inx
		dey
		bne 	_TOIALoop
_TOIANo:
		ldx 	zTemp0 						; restore YX = slot address
		ldy 	zTemp0+1
		clc 								; CC = not an implicitly-registered array
		rts

		.send code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		rem.asm
;		Purpose:	Handle remark (ignore to EOL)
;		Created:	20th April 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;								REM consumes the rest of the line.
;
; ************************************************************************************************

CommandREM: 
		jsr 	LookNext
		beq 	_CRExit
		jsr 	GetNext
		bra 	CommandREM
_CRExit:		
		rts

		.send code


; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		reset.asm
;		Purpose:	Reset information storage
;		Created:	15th April 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;								Reset the storage (variables,line#)
;
; ************************************************************************************************

STRReset:

		lda	 	compilerStartHigh 			; set up the two table pointers
		sta 	variableListEnd+1
		stz 	variableListEnd

		lda 	compilerEndHigh
		sta 	lineNumberTable+1
		stz 	lineNumberTable

		.varstore_access 				; clear the head of the work area list.

		;
		;		This read the LOW byte of variableListEnd (just zeroed two lines above) into the
		;		HIGH byte of zTemp0, so it wrote its terminator to $0000 -- on the X16 that is the
		;		RAM BANK register, not the table -- and left the real head at compilerStartHigh:$00
		;		holding whatever was there. It only ever appeared to work because the head happens
		;		to be zero on a cold boot; a second compile in the same session inherited the first
		;		compile's list. FindVariable walks from the head, so a non-zero byte there sends it
		;		off through garbage records.
		;
		lda 	variableListEnd+1
		sta 	zTemp0+1
		stz 	zTemp0
		lda 	#0
		sta 	(zTemp0)

		.varstore_release
		.set16 freeVariableMemory,0 		; clear the free variable memory record.
		rts
		.send code

		.section storage
lineNumberTable:							; line number table, works down.
		.fill 	2		
variableListEnd:							; known variables, works up.
		.fill 	2	
freeVariableMemory: 						; next free memory slot
		.fill 	2
storageScratch: 							; one byte of working space for the table-collision
		.fill 	1 							; test in CreateVariableRecord (X and Y are busy there)
		.send storage

